(window.GIM_TS=window.GIM_TS||{})["Nazir.0"]={"from":0,"a":[["\u0003כל כינויי נזירות\u0004 כאשר אדם מקבל על עצמו נזירות לא באמירת המלה \"נזיר\" אלא באחד הכינויים המנויים בדברי חכמים — הרי זה \u0003כ\u0004קבלת \u0003נזירות\u0004 בלשון \"נזיר\", וחל נדר הנזירות עליו. וכן חלה עליו נזירות אם משתמש לקבלת נזירות ב\"ידות\" נזירות, שאומר דיבור סתום או בלתי מושלם, ומתוך ההקשר מבינים שכוונתו לנזירות.","ולכן, \u0003האומר \"אהא\"\u0004 ולא פירש מה — \u0003הרי זה נזיר, או\u0004 שאומר \u0003\"אהא נאה\"\u0004 — הריהו \u0003נזיר,\u0004 וכאשר יבוארו הדברים לדיוקם בגמרא. וכינויי נזירות: האומר \u0003\"\u0004הריני \u0003נזיק\",\u0004 או \u0003\"\u0004הריני \u0003נזיח\",\u0004 או \u0003\"\u0004הריני \u0003פזיח\" —\u0004 \u0003הרי זה נזיר.\u0004 אם אומר \u0003\"הריני כזה\"\u0004 או \u0003\"הריני מסלסל\",\u0004 או \u0003\"הריני מכלכל\",\u0004 או \u0003\"הרי עלי לשלח פרע\",\u0004 בכל אלה — \u0003הרי זה נזיר.\u0004","האומר \u0003\"הרי עלי ציפורים\"\u0004 — \u0003ר' מאיר אומר:\u0004 הריהו \u0003נזיר,\u0004 שכוונתו לנדר נזירות, אף כי השתמש בלשון עקיפה כדי לומר זאת. \u0003וחכמים אומרים: אינו נזיר.\u0004","תחילה מבררים מה מקומה של המסכת בסדר נשים שבששה סדרי משנה. \u0003מכדי\u0004 \u0005[הלא\u0006\u0005]\u0006 ה\u0003תנא\u0004 \u0003בסדר נשים קאי\u0004 \u0005[עומד,\u0006 נמצא\u0005],\u0006 ואם כן \u0003מאי\u0004 \u0003טעמא תני\u0004 \u0005[מה טעם שנה\u0006\u0005]\u0006 את מסכת \u0003נזיר\u0004 כאן, בסדר נשים? שהרי, לכאורה, אין עניינה כלל לסדר זה!","ומשיבים: ה\u0003תנא אקרא קאי\u0004 \u0005[על הכתוב עומד,\u0006 נמצא\u0005],\u0006 שהוא מתייחס למה שנאמר בענין גירושי אשה: \u0003\"והיה אם לא תמצא חן בעיניו כי מצא בה ערות דבר\"\u0004 (דברים כד, א). \u0003והכי קאמר\u0004 \u0005[וכך אמר\u0006\u0005],\u0006 כלומר, זו כוונת הדברים: \u0003מי גרם לה לעבירה\u0004 של האשה (\"ערות דבר\") — \u0003יין, וקאמר\u0004 \u0005[ואמר\u0006\u0005]\u0006 החכם: \u0003כל הרואה סוטה בקלקולה\u0004 (בחטאה ובעונשה) \u0003יזיר עצמו מן היין,\u0004 ומשום כך קבע התנא את מסכת נזיר סמוך למסכת סוטה, שהן קשורות למסכת גירושין, וכל אלה שייכות לסדר נשים.","לאחר מכן מבררים את סדר הדברים במשנה, שאינו ברור כל כך, שהרי התנא \u0003פתח בכינויין\u0004 שאמר שכל כינויי נזירות כנזירות, \u0003ומפרש\u0004 כדוגמא ללשונות אלה מייד לאחר מכן לא כינויי נזירות, אלא \u0003ידות,\u0004 כלומר, ביטויים מקוצרים שאין בהם הזכרת שם נזירות מפורשת, אך אפשר ללמוד מהם ענין זה (כמו ידית של כלי שאינה הכלי עצמו אבל על ידה מחזיקים בכלי).","\u0003אמר רבא ואיתימא כדי\u0004 \u0005[ויש אומרים\u0006 שמועה זו סתם\u0005]\u0006 בלי ציון שמו של חכם מסויים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה בלשונה וכך היא שנויה\u0005],\u0006 כך יש להבין אותה: \u0003כל כינויי נזירות כנזירות, ו\u0004כן כל \u0003ידות נזירות כנזירות, ואלו הן ידות: האומר \"אהא\" —\u0004 \u0003הרי זה נזיר.\u0004","ושואלים: גם אם נאמר שיש לשנות במשנה ענין ידות, מכל מקום \u0003ולפרוש כינויי ברישא\u0004 \u0005[ויפרש\u0006 התנא דינם של כינויים בתחילה\u0005]\u0006 ואחר כך יפרש את דין הידות, שהרי זהו סדר הדברים בראשית המשנה! ומשיבים: ה\u0003תנא מההוא דסליק\u0004 \u0005[מאותו\u0006 דבר שבו הוא סיים\u0005] —\u0006 \u0003ההוא\u0004 \u0005[אותו\u0006\u0005]\u0006 הוא \u0003מפרש ברישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 כשהוא מפרט את הדברים. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006\u0005]\u0006 במשנה במסכת שבת, שפותחת: \u0003\"במה מדליקין\u0004 נר שבת \u0003ובמה אין מדליקין\",\u0004 \u0003ומפרש\u0004 את הפרטים של \u0003\"אין מדליקין\" ברישא\u0004 \u0005[בתחילה\u0006\u0005].\u0006","וכן מתחיל התנא משנה אחרת במסכת שבת: \u0003\"במה טומנין\u0004 את האוכל בשבת \u0003ובמה אין טומנין\",\u0004 \u0003ומפרש \"אין טומנין\" ברישא\u0004 \u0005[בתחילה\u0006\u0005].\u0006","וכן במשנה \u0003\"במה אשה יוצאה\u0004 בשבת לרשות הרבים \u0003ובמה אינה יוצאה\"\u0004 \u0003ומפרש \"לא תצא אשה\"\u0004 ומפרט את כל הדברים האסורים \u0003ברישא\u0004 \u0005[בתחילה\u0006\u0005].\u0006 ומקשים: האם דבר זה הוא כלל קבוע?","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"במה בהמה יוצאה\u0004 לרשות הרבים בשבת \u0003ובמה אינה יוצאה\"\u0004 \u0003ומפרש \"יוצא גמל\" ברישא\u0004 \u0005[בתחילה\u0006\u0005].\u0006","וכן שנה במשנה בבבא בתרא: \u0003\"יש נוחלין\u0004 (יורשים) \u0003ומנחילין\u0004 (מורישים), \u0003נוחלין ולא מנחילין, מנחילין ולא נוחלין, לא נוחלין ולא מנחילין\",\u0004 ואחר כך מפרט אותם, \u0003ומפרש \"אלו נוחלין ומנחילין\" ברישא\u0004 \u0005[בתחילה\u0006\u0005].\u0006 ואם כן אין זה סדר קבוע במשנה שמפרט התנא קודם את הכלל האחרון!","\u0003אלא, לעולם\u0004 יש לפרש כי \u0003תני הכי ותני הכי\u0004 \u0005[שנה כך ושנה כך\u0006\u0005],\u0006 שפעמים מתחיל לפרט את הכלל הראשון, ופעמים את הכלל האחרון.","\u0003אלא\u0004 שיש טעם לשינויים אלה בסדר, \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 במשניות \"במה מדליקין\", \"במה טומנין\" ו\"במה אשה יוצאה\", \u0003דאיסורא דנפשיה\u0004 \u0005[שאיסור ש\u0006חל על האדם עצמו\u0005]\u0006 \u0003הוא —\u0004 \u0003מפרש איסורא דנפשיה ברישא\u0004 \u0005[\u0006את האיסור שחל על עצמו בתחילה\u0005]\u0006 מפני חומרתו, ואילו \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003בהמה\u0004 (\"במה בהמה יוצאה\") \u0003דאיסורא איידי\u0004 \u0005[שהאיסור על ידי\u0006\u0005]\u0006 \u0003בהמה הוא דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 ואינו חל על האדם עצמו — \u0003מפרש\u0004 את \u0003היתירא ברישא\u0004 \u0005[ההיתר בתחילה\u0006\u0005].\u0006"],["\u0003גבי \"יש נוחלין\" נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 יש טעם בדבר שפירט תחילה את האמור בתחילת הדברים, כי \u0003מפרש עיקר נחלה\u0004 הכתובה בתורה \u0003ברישא\u0004 \u0005[בתחילה\u0006\u0005],\u0006 ירושת הבנים את האב.","ומעתה, שנוכחנו כי אין סדר קבוע לדבר, חוזרת השאלה: \u0003אלא\u0004 \u0005[הכא\u0006 \u0005[כאן\u0006\u0005]\u0006 \u0005]\u0006 \u0003לפרוש כינויי ברישא\u0004 \u0005[שיפרש\u0006 את הכינויים בתחילה\u0005]!\u0006 \u0003אלא היינו\u0004 \u0005[זהו\u0006\u0005]\u0006 ה\u0003טעם: ידות, הואיל ואתיין ליה מדרשא\u0004 \u0005[ובאו,\u0006 נלמדו, מדרשה\u0005]\u0006 של חכמים ואין להם מקור מפורש בתורה, לכן הם \u0003חביבין ליה\u0004 \u0005[לו\u0006\u0005]\u0006 לתנא משום החידוש שבהם, ולכן פתח בהם.","ושואלים: אם כן \u0003וליפתח בהון ברישא\u0004 \u0005[שיפתח בהם בתחילה\u0006\u0005]\u0006 וישנה קודם \"כל ידות נזירות\" ואחר כך \"כל כינויי נזירות\" וכו'! ומשיבים: ה\u0003תנא כי\u0004 \u0005[כאשר\u0006 הוא\u0005]\u0006 \u0003מתחיל —\u0004 \u0003מתחיל בעיקר קרבן\u0004 הנזירות, כלומר, בדבר שיש לו עיקר בתורה, \u0003ולענין פירושי\u0004 \u0005[פירוש\u0006\u0005]\u0006 — \u0003מפרש ידות ברישא\u0004 \u0005[בתחילה\u0006\u0005],\u0006 מפני שנושא זה חביב בעיניו.","ומכאן לביאור דברי המשנה לפרטיהם. שנינו שם: \u0003האומר \"אהא\"\u0004 — \u0003הרי זה נזיר.\u0004 ושואלים: \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003\"אהא בתענית\" קאמר\u0004 \u0005[אומר\u0006 הוא\u0005]?\u0006 ואין כוונתו כלל לנדר נזירות, אלא לנדר תענית! \u0003אמר שמואל:\u0004 מדובר במשנתנו \u0003כגון שהיה נזיר עובר לפניו\u0004 ואמר \"אהא\", וכיון שאמר \"אהא\" מובן מזה שלנזירות התכוון.","ומבררים: \u0003לימא\u0004 \u0005[האם לומר\u0006\u0005]\u0006 מתוך דברי שמואל אלה \u0003קסבר\u0004 \u0005[שסבור\u0006\u0005]\u0006 \u0003שמואל\u0004 שככלל \u0003ידים שאינן מוכיחות,\u0004 חלקי דיבור שאין בהם כדי להוכיח מתוכם את כוונתו של האומר, \u0003לא הוויין\u0004 \u0005[אינן\u0006\u0005]\u0006 נחשבות \u0003ידים\u0004 מחייבות כלל? את ההצעה הזו דוחים, \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 אין להסיק מכאן דבר זה, שכן \u0003בזמן שנזיר עובר לפניו —\u0004 \u0003ליכא לספוקא במילתא\u0004 \u0003אחרינא\u0004 \u0005[אין להסתפק בדבר אחר\u0006\u0005]\u0006 מהי כוונתו של האומר, והרי זו יד לנזירות. \u0003אבל ודאי\u0004 כאשר \u0003אין הנזיר עובר לפניו\u0004 והוא אמר \"אהא\", \u0003אמרינן\u0004 \u0005[אומרים אנו\u0006\u0005]:\u0006 \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003\"אהא בתענית\" קאמר\u0004 \u0005[אומר\u0006 הוא\u0005],\u0006 ויש לומר שדווקא במקרה כזה שהידים אינן מוכיחות כלל, צריך שיהיה סימן כלשהו להוכיח למה כוונתו.","ושואלים: ואף כשהיה נזיר עובר לפניו ואמר \"אהא\" מדוע חלה עליו נזירות בכך, \u0003ודלמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 \u0003לפוטרו מן קרבנותיו קאמר\u0004 \u0005[אומר\u0006 הוא\u0005]?\u0006 שהתכוון לומר: \"אהא במקומו\" לענין הממון, וכוונתו לומר שנדר להביא על חשבונו את הקרבנות שחייב בהם הנזיר הזה, ולפוטרו מן העול הכספי! ומשיבים: כאן מדובר \u0003דקאמר\u0004 \u0005[ש\u0006הוא אומר\u0005]\u0006 \u0003בלבו\u0004 שמקבל על עצמו נזירות.","ושואלים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך, מה\u0006 יש לומר\u0005],\u0006 מה חידוש יש בהלכה זו, שהרי התכוון לנדור נדר נזירות! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005]\u0006 שיהיו \u0003פיו ולבו שוין,\u0004 וצריך לבטא בפיו בדיוק מה שהוא אומר בליבו, ואילו כאן בפיו רק אמר \"אהא\" ובליבו אמר שיהיה נזיר, ואם כן לא תחול עליו נזירות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שכיון שהדבר שאמר יכול להתפרש בדרך זו, ובליבו היה להיות נזיר — הריהו נעשה נזיר.","שנינו במשנה: האומר \u0003\"אהא נאה\"\u0004 — הריהו \u0003נזיר.\u0004 ושואלים: \u0003ודלמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 כשאמר \"אהא נאה\" התכוון לומר: \u0003אנאה\u0004 (אהיה נאה) \u0003לפניו במצות? כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"זה אלי ואנוהו\"\u0004 (שמות טו, ב) שמפרשים \"אנוהו\" מלשון נוי, וכוונתו — \u0003אנאה\u0004 \u0003לפניו במצות.\u0004 כיצד? \u0003אעשה לפניו סוכה נאה, לולב נאה, ציצית נאה, אכתוב לפניו ספר תורה נאה ואכרכנו בשיראין\u0004 (בבגדי משי) \u0003נאים,\u0004 ואם כן אף \"אהא נאה\" יכול להתפרש גם בדרך אחרת!","\u0003אמר שמואל:\u0004 מדובר פה \u0003שתפוס\u0004 (שמחזיק) באותה שעה \u0003בשערו, ואמר \"אנאה\"\u0004 ולכן מובן מכאן שרצונו להיות נאה בנזירות.","ותמהים לגופו של דבר: הרי \u0003נזירא\u0004 \u0005[הנזירות\u0006\u0005]\u0006 הריהי \u0003מילתא\u0004 \u0005[דבר\u0006\u0005]\u0006 של \u0003עבירה\u0004 היא, כאשר יבואר שחכמים רואים עבירה בנזירות, \u0003ואמרינן ליה\u0004 \u0005[ואומרים\u0006 וקוראים אנו לו לנזיר\u0005]\u0006 \u0003\"נאה\"?\u0004"],["ומשיבים: \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 יש בנזירות צד נוי של מצוה, ש\u0003אפילו ל\u0004שיטת \u0003ר' אלעזר הקפר\u0004 ש\u0003אמר: נזיר חוטא\u0004 הוא, \u0003הני מילי\u0004 \u0005[דברים אלה\u0006\u0005]\u0006 אמורים דווקא \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר טמא\u0004 שנטמא ומביא קרבן חטאת, כאמור: \"וכיפר עליו מאשר חטא על הנפש\" (במדבר ו, יא), ולדעת ר' אלעזר הקפר הרי זה קרבן על עצם הנזירות, \u0003דאיידי דבעי מיסתר\u0004 \u0005[שמתוך שצריך לסתור\u0006\u0005]\u0006 את ימי נזירותו הראשונים, וצריך למנות מחדש ימי נזירותו, שכן \u0003אמר רחמנא\u0004 \u0005[אמרה התורה\u0006\u0005]\u0006 \u0003\"והימים הראשנים יפלו כי טמא נזרו\"\u0004 (במדבר ו, יב), \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003הוא\u0004 שאומר ר' אלעזר כך, יש חשש \u0003דלמא אתי למיעבר על נזירותיה\u0004 \u0005[שמא יבא לעבור על נזירותו\u0006\u0005]\u0006 מפני ריבוי הזמן שהוא יותר מכפי ששיער תחילה, \u0003אבל נזיר טהור לאו\u0004 \u0005[לא\u0006\u0005]\u0006 \u0003חוטא קרי ביה\u0004 \u0005[קוראים בו,\u0006 לו\u0005].\u0006","עוד שנינו במשנה, האומר: \u0003\"הריני כזה\"\u0004 — הריהו נזיר. ושואלים: \u0003נהי נמי\u0004 \u0005[אם אמנם גם כן\u0006\u0005]\u0006 ש\u0003תפוס,\u0004 שהוא מחזיק אותה שעה \u0003בשערו\u0004 כפי שהוסבר לעיל ב\"אהא נאה\", הרי \u0003\"הריני\u0004 נזיר \u0003כזה\"\u0004 — \u0003לא אמר,\u0004 וכיצד יש בדבר זה קבלת נזירות? \u0003אמר שמואל: כגון שהיה נזיר עובר לפניו\u0004 בשעה שאמר כן. והתכוון איפוא לומר: הריני כמו אדם זה, נזיר כמוהו, ולכן יש בכך משמעות נזירות.","שנינו במשנה: האומר \u0003\"הריני מסלסל\"\u0004 — הרי זה נזיר. ושואלים: \u0003ממאי דהדין\u0004 \u0005[מניין ש\u0006\"מסלסל\" זה\u0005]\u0006 \u0003סלסול שערא\u0004 \u0005[שיער\u0006\u0005]\u0006 הוא? ומשיבים: \u0003כדאמרה ליה ההיא אמתא דבי רבי לההוא גברא\u0004 \u0005[כמו שאמרה לו אותה שפחה של בית רבי\u0006 יהודה הנשיא \u0005לאדם אחד]\u0006 שהיה מתעסק בגידול שערותיו: \u0003עד מתי אתה מסלסל בשערך?\u0004 משמע שסלסול הוא גידול שיער.","ושואלים: \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 שהכוונה היא לעסק ה\u0003תורה, דכתיב\u0004 \u0005[ש\u0006כן נאמר\u0005]\u0006 בה \u0003\"סלסלה ותרוממך\"\u0004 (משלי ד, ח), ושמא התכוון לנדור שיהא מסלסל ומתעסק בדברי תורה? \u0003אמר שמואל: הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 מדובר \u0003שתפוס בשערו\u0004 באותה שעה שאמר כן.","שנינו במשנה שהאומר \u0003\"הריני מכלכל\"\u0004 — הרי זה נזיר. ושואלים: \u0003ממאי דהדין\u0004 \u0005[מניין ש\"\u0006 מכלכל\" זה\u0005]\u0006 \u0003כילכול שערו הוא?\u0004 ומשיבים: \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 מהו שיעור הפחות ביותר של \u0003סיד\u0004 שחייב עליו אם מוציאו בשבת מרשות היחיד לרשות הרבים? \u0003ר' יהודה אומר: כדי לסוד כילכול. ואמר רב:\u0004 מה פירושו של כילכול זה — \u0003בת צידעא,\u0004 שיער הראש שמתחת לצדעיים.","ומקשים: \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 שהיתה כוונתו לנדור \u0003מיזן עניי\u0004 \u0005[לזון עניים\u0006\u0005],\u0006 \u0003כדכתיב\u0004 \u0005[כפי שנאמר\u0006\u0005]:\u0006 \u0003\"ויכלכל יוסף את אביו ואת אחיו\"\u0004 (בראשית מז, יב)? \u0003אמר שמואל: הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 מדובר \u0003שתפוס בשערו\u0004 ומובן מכאן שהתכוון לכילכול שיער.","עוד שנינו במשנה, שהאומר \u0003\"הרי עלי לשלח פרע\" —\u0004 \u0003הרי זה נזיר.\u0004 ושואלים: \u0003ממאי דהדין\u0004 \u0005[ממה\u0006 יודעים שזה\u0005]\u0006 \u0003שילוח ריבויא הוא\u0004 \u0005[\u0006לשון ריבוי וגידול\u0005]\u0006 \u0003הוא?\u0004 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"שלחיך פרדס רמונים\"\u0004 (שיר השירים ד, יג). כלומר, מחלפות שערותיך הן כפרדס רמונים.","ושואלים: \u0003אימא מידי דעבורי\u0004 \u0005[אמור\u0006 שהכוונה היא דבר של העברה והסרה\u0005],\u0006 \u0003כדכתיב\u0004 \u0005[כמו שנאמר\u0006\u0005]\u0006 \u0003\"ושלח מים על פני חוצות\"\u0004 (איוב ה, י), שמפרשים אותו במשמעות של העברת המים ממקום למקום, ושמא שילוח פרע זה שאמר משמעו שנודר שיעביר = יסיר את שערו!","ומשיבים: ה\u0003תנא\u0004 שלנו מן הגזירה שווה של המלים \u0003\"פרע\" \"פרע\" יליף\u0004 \u0005[\u0006הוא לומד\u0005]\u0006 ששילוח מובנו גידול שיער, שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן\u0006\u0005]\u0006 בנזיר: \u0003\"קדש יהיה גדל פרע\"\u0004 (במדבר ו, ה), \u0003וכתיב התם גבי\u0004 \u0005[וכתוב שם אצל\u0006\u0005]\u0006 \u0003כהן הדיוט\u0004 העובד בבית המקדש — \u0003\"ופרע לא ישלחו\"\u0004 (יחזקאל מד, כ), משמע ששילוח פרע משמעו גידול שיער.","ומוסיפים עוד תשובה: \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 \u0003האי\u0004 \u0005[\u0006כתוב זה\u0005]\u0006 \u0003\"שולח מים\" נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 לשון \u0003ריבוי הוא, כדמתרגם\u0004 \u0005[כפי שמתרגם\u0006\u0005]\u0006 \u0003רב יוסף\u0004 פסוק זה בארמית: \u0003דכד משקין ליה מיא לפירא ורבי\u0004 \u0005[שכאשר משקים אותו מים לפרי וגדל\u0006\u0005],\u0006 ומשמעות הכתוב היא — שמגדל (\"שולח\") דברים על ידי המים.","שנינו במשנה: האומר \u0003\"הרי עלי ציפרין\"\u0004 — \u0003ר' מאיר אומר:\u0004 הריהו נעשה \u0003נזיר\u0004 בכך. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003ר' מאיר? אמר ריש לקיש: ציפרין סמוכין לשיער קיבל עליו, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 \u0003\"עד די שעריה כנשרין רבה וטפרוהי כצפרין\"\u0004 (דניאל ד, ל) \u0005[עד ששערו כנשרים גדל וציפורניו כציפורים\u0006\u0005],\u0006 שכיון שבפסוק זה יש סמיכות בין ציפורים וגידול שיער, הרי אף כאשר אמר \"הרי עלי ציפרין\" — לגידול שיער התכוון.","ומסבירים את המחלוקת שבמשנתנו, \u0003ר' מאיר סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003מתפיס איניש\u0004 \u0005[אדם\u0006\u0005]\u0006 את דבריו \u0003במידי דסמיך ליה\u0004 \u0005[בדבר שסמוך לו\u0006\u0005],\u0006 שאף שציפורים נזכרו לגבי גידול ציפורניים, מכל מקום כיון שבפסוק זה נזכר גם גידול שיער, היתה כוונתו לנדר המתייחס לחלקו האחר של הפסוק."],["\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים\u0006\u0005]:\u0006 \u0003לא מתפיס איניש במידי דסמיך ליה\u0004 \u0005[אדם בדבר הסמוך לו\u0006\u0005]\u0006 ולא היתה כוונתו לכך.","\u0003ר' יוחנן אמר: דכולי עלמא\u0004 \u0005[לדעת הכל\u0006\u0005]\u0006 \u0003לא מתפיס\u0004 אדם על ידי רמז לדבר הסמוך לכך במקרא. \u0003אלא, היינו טעמא\u0004 \u0005[זהו הטעם\u0006\u0005]\u0006 של \u0003ר' מאיר: דחיישינן\u0004 \u0005[שחוששים אנו\u0006\u0005]\u0006 \u0003שמא צפורי נזיר טמא קיבל עליו,\u0004 שנזיר שנטמא מביא ציפורים (תורים או בני יונה) כקרבן לטהרתו, וכשאמר \"הרי עלי ציפורים\" התכוון לנדר נזיר שאם ייטמא צריך להביא ציפורים.","ושואלים: לדברי ר' יוחנן \u0003מכדי \"חיישינן\" קאמר\u0004 \u0005[הלא\u0006 לשיטת ר' מאיר רק \"חוששים אנו\" אמר\u0005]\u0006 ואין כאן נדר ברור, ואם כן \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 לא נזירות קיבל עליו אלא \u0003צפורי נדבה קיבל עליו,\u0004 שנדר רק להביא תורים או בני יונה לעולה, ומדוע אומרים שנתכוון כלל לנזירות? ומשיבים: \u0003אם כן,\u0004 שרצה להביא נדבה, \u0003\"הרי עלי קן\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שזו הלשון הרגילה כשנודרים להביא עופות לקרבן.","ושואלים עוד: \u0003ודלמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 \u0003\"הרי עלי צפורי מצורע\" קאמר\u0004 \u0005[אומר הוא\u0006\u0005],\u0006 שהתכוון שהוא מקבל על עצמו להביא ציפורים במקום מצורע (ראה ויקרא יד, ד)? ומשיבים: כאן מדובר \u0003כגון ש\u0004בשעה שאמר את דבריו \u0003היה נזיר עובר לפניו,\u0004 ולכן מבינים את הדברים במשמעות של נזירות. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 היה זה \u0003נזיר טמא, ולפוטרו מן קרבנותיו\u0004 על ידי הבאת ציפורים עבורו \u0003קאמר\u0004 \u0005[הוא אומר\u0006\u0005]?!\u0006 ומשיבים: \u0003כגון שהיה נזיר טהור עובר לפניו,\u0004 ואז יש לומר שהתכוון בכך לקבל על עצמו נזירות.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל ביניהם\u0005],\u0006 בין פירוש ריש לקיש לפירושו של ר' יוחנן, אם לשניהם צריך לפרש שמדובר דווקא כאשר היה נזיר עובר לפניו?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006\u0005]\u0006 הבדל בשיטת ר' מאיר \u0003כגון\u0004 ש\u0003אמר\u0004 במפורש: \u0003\"ציפרין הסמוכין לשער עלי\", לר' יוחנן אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003אמר הכי\u0004 \u0005[כך\u0006\u0005]\u0006 בלשון זו, \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003נזיר עובר לפניו —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 הרי זה נדר נזירות, \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003לא\u0004 היה נזיר עובר לפניו — \u0003לא.\u0004 ואילו \u0003לר' שמעון בן לקיש אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003אין נזיר עובר לפניו\u0004 מכל מקום נדר נזירות הוא, כי לדעתו מתפיס אדם בדבר הסמוך בכתוב.","ושואלים: \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר\u0006\u0005]\u0006 ש\u0003לא מתפיס איניש\u0004 \u0005[אדם\u0006\u0005]\u0006 נדר \u0003במילתא דסמיך ליה\u0004 \u0005[בדבר הסמוך לו\u0006\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר \"ימין\" —\u0004 \u0003הרי זו\u0004 לשון \u0003שבועה,\u0004 שאם אמר \"ימין שאין אני אוכל ככר זו\" — הרי זה כנשבע שלא יאכלנה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר — \u0003לאו\u0004 \u0005[\u0006האם לא\u0005]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 \u0003\"וירם ימינו ושמאלו אל השמים וישבע בחי העולם\"\u0004 (דניאל יב, ז), שלשון \"ימין\" נחשבת כשבועה משום שהיא נזכרת סמוך ללשון שבועה בכתוב?","ודוחים, \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003לא,\u0004 הטעם הוא \u0003משום\u0004 ש\u0003\"ימין\" גופיה\u0004 \u0005[עצמה\u0006\u0005]\u0006 \u0003איקרי\u0004 \u0005[נקראת\u0006\u0005]\u0006 \u0003שבועה. דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003מניין לאומר \"ימין\" שהיא שבועה —\u0004 \u0003שנאמר: \"נשבע ה' בימינו\"\u0004 (ישעיה סב, ח), \u0003מניין לאומר \"שמאל\" שהיא שבועה שנאמר: \"ובזרוע עזו\"\u0004 (ישעיה סב, ח), שכיון שנאמרה בהקבלה לימין משמע שהיא יד שמאל. ומכאן שלשון \"ימין\" ו\"שמאל\" היא עצמה לשון שבועה, ואין זו התפסה בדבר הסמוך לו בכתוב.","אמר אדם: \u0003\"הריני נזיר מן החרצנים\" ו\u0004כן אם אמר \u0003\"\u0004הריני נזיר \u0003מן הזגים\" ו\u0004כן מי שאמר \u0003\"\u0004הריני נזיר \u0003מן התגלחת\" ו\u0004כן \u0003\"מן הטומאה\" —\u0004 \u0003הרי זה נזיר, וכל דקדוקי נזירות עליו.\u0004 שלא רק מה שקיבל על עצמו חל עליו, אלא חלים עליו כל דיני נזיר, גם בדברים שלא הזכיר שמקבל על עצמו.","מעירים: \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' שמעון\u0004 היא. \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: אינו חייב\u0004 לקיים נדר נזירות \u0003עד שידור מכולם,\u0004 מכל הדברים האמורים בנזיר. \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים\u0006\u0005]:\u0006 \u0003אפילו לא נזר אלא בחד מנהון\u0004 \u0005[באחד מהם\u0006\u0005]\u0006 — \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 בכך \u0003נזיר.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003ר' שמעון —\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 בפרשת הנזיר: \"כל ימי נזרו \u0003מכל אשר יעשה מגפן היין מחרצנים ועד זג\u0004 לא יאכל\" (במדבר ו, ד), לומר שצריך לידור נזירות מכל האיסורים. ומבררים: \u0003ורבנן מאי טעמייהו\u0004 \u0005[וחכמים מה טעמם\u0006\u0005]?\u0006 — \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"מיין ושכר יזיר\"\u0004 (במדבר ו, ג), משמע שאם הוא נודר מיין ושיכר בלבד, נכללים בענין זה כל דיני הנזירות כולם.","ושואלים: \u0003ור' שמעון נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"מיין ושכר יזיר\"!\u0004 ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב נצרך לו\u0005]\u0006 ללמד דבר אחר — \u0003לאסור\u0004 על הנזיר \u0003יין מצוה כיין הרשות.\u0004","ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא\u0006\u0005]\u0006 יין מצוה — יין של \u0003קדושתא ואבדלתא\u0004 \u0005[קידוש והבדלה\u0006\u0005]?\u0006"],["\u0003הרי מושבע ועומד עליו מהר סיני,\u0004 לקיים דין נזירות, ואילו מצות הקידוש אינה אלא מדברי סופרים בלבד, ובודאי חל איסור שתיית יין על אלה! (רמב\"ם).","\u0003אלא\u0004 צריך הכתוב הזה ללמדנו \u0003כי הא\u0004 \u0005[כמו זו\u0006\u0005]\u0006 ש\u0003אמר רבא:\u0004 אם אמר אדם \u0003\"שבועה שאשתה\u0004 יין \u0003\"\u0004, \u0003וחזר\u0004 אחר כך \u0003ואמר \"הריני נזיר\" —\u0004 \u0003אתיא\u0004 \u0005[באה\u0006\u0005]\u0006 \u0003נזירות חיילא\u0004 \u0005[\u0006וחלה\u0005]\u0006 \u0003על שבועה\u0004 ואסור בשתיית יין. שלמרות שהיין הזה הוא בשבילו יין מצוה — מכל מקום חל עליו איסור הנזירות לשתותו.","ושואלים: \u0003ורבנן נמי הא מיבעי ליה\u0004 \u0005[וחכמים גם כן, הרי צריכים הם\u0006\u0005]\u0006 כתוב זה \u0003לאסור\u0004 על הנזיר \u0003יין מצוה כיין רשות,\u0004 וכיצד למדים הם ממנו דין אחר! ומשיבים: אם זו בלבד היתה כוונת הכתוב ללמדנו, \u0003אם כן,\u0004 \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב\u0006\u0005]\u0006 \u0003\"מיין\u0004 יזיר \u0003\"\u0004בלבד, \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 מלמדנו \u0003\"ושכר\" —\u0004 \u0003שמעת מינה תרתי\u0004 \u0005[שומע,\u0006 לומד אתה מכאן שני דברים\u0005].\u0006","ושואלים: \u0003ור' שמעון\u0004 מה משיב הוא על כך? ומשיבים: לשיטתו \u0003היינו טעמא\u0004 \u0005[זהו הטעם\u0006\u0005]\u0006 ש\u0003כתב\u0004 המקרא \u0003\"שכר\" —\u0004 \u0003לאלופי\u0004 \u0005[ללמד\u0006\u0005]\u0006 מכאן גזירה שווה של המילים \u0003\"שכר\" \"שכר\" ל\u0004ענין ביאה ועבודה ב\u0003מקדש. דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 לאהרון הכהן: \u0003\"יין ושכר אל תשת אתה ובניך אתך\u0004 בבואכם אל אוהל מועד\u0003\"\u0004 (ויקרא י, ט), ללמדנו: \u0003מה גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר יין\u0004 בלבד \u0003הוא דליתסר\u0004 \u0005[שנאסר\u0006\u0005]\u0006 בו, \u0003אבל שאר משקין —\u0004 \u0003לא, אף גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003מקדש נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003יין הוא דליתסר\u0004 \u0005[שנאסר\u0006\u0005],\u0006 \u0003אבל שאר משקין המשתכרין\u0004 (המשכרים) — \u0003לא\u0004 נאסרו בהם הכהנים, אף שאפשר היה לחשוב שהם אסורים משום שיכר.","\u0003ולאפוקי\u0004 \u0005[ולהוציא\u0006\u0005]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה\u0004 בענין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אכל דבילה קעילית\u0004 שהיא מתוקה ביותר עד כדי שיכרון, \u0003ו\u0004כן אם \u0003שתה דבש וחלב, ונכנס למקדש —\u0004 \u0003חייב,\u0004 שחל עליו האיסור משום \"שיכר\", ששתה או אכל דבר המשכר.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור\u0006\u0005]\u0006 באופן אחר לאיזה ענין נזקק ר' שמעון ל\"מיין ושכר יזיר\": \u0003ר' שמעון לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את הרעיון של \u0003איסור חל על איסור,\u0004 שלדעתו אם יש כבר איסור קודם על דבר — לא חל עליו איסור נוסף.","\u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: האוכל נבילה ביום הכפורים —\u0004 \u0003פטור\u0004 מכרת על אכילה ביום הכיפורים, משום שחל כבר איסור נבילה על הדבר, ואין איסור (יום הכיפורים) חל על איסור (נבילה). ולכן היה צריך לומר שבענין נזירות חל איסור על איסור, שגם אם נשבע שלא לשתות יין ואחר כך נזר — חלים עליו שני איסורים.","ושואלים לצד שני: \u0003ולרבנן נמי\u0004 \u0005[ול\u0006דעת חכמים גם כן\u0005]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"מכל אשר יעשה מגפן היין\"\u0004 (במדבר ו, ד), ומשמע מכאן כשיטת ר' שמעון שצריך לידור מכל איסורי הנזיר! ומשיבים: \u0003אמרי\u0004 \u0005[\u0006יכולים לומר\u0005]\u0006 \u0003לך רבנן\u0004 \u0005[חכמים\u0006\u0005]:\u0006 \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 הכתוב \u0003לימד\u0004 דבר אחר — \u0003על איסורי נזיר שמצטרפים זה עם זה,\u0004 כלומר, שאם הנזיר אוכל דברים שונים שהוא אסור בהם (ענבים, יין, זגים) ואין באחד מהם כזית אלא רק בכולם יחד — הריהם מצטרפים, ולוקה עליהם משום שעבר על הלאו שבתורה.","ומסבירים: \u0003ור' שמעון\u0004 לא למד כן מהפסוק, משום ש\u0003לית ליה\u0004 \u0005[אין לו\u0006\u0005]\u0006 דין \u0003צירוף, דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 האוכל \u0003כל שהו\u0004 מדבר אסור, הרי זה שיעור \u0003ל\u0004חייבו \u0003מכות, לא אמרו\u0004 בכל מקום שיעור \u0003כזית אלא לענין קרבן,\u0004 שהאוכל דבר אסור שיש באכילתו בשגגה חיוב חטאת, צריך שיהא באכילה שיעור כזית. ולפיכך בנזיר שאין בו חיוב קרבן על אכילת האיסור, אין צורך בפסוק מיוחד ללמדנו דין צירוף אכילות לכזית, ולא בא הפסוק אלא ללמד כיצד צריך להיות הנדר שהנזיר מקבל על עצמו.","אמר אדם: \u0003\"הריני כשמשון\", \"כבן מנוח\", \"כבעל דלילה\", \"כמי שעקר דלתות עזה\", \"כמי שנקרו פלשתים את עיניו\" —\u0004 \u0003הרי זה נזיר שמשון\u0004 שדיניו מפורשים להלן.","שואלים: \u0003למה לי למיתנא\u0004 \u0005[לשנות\u0006\u0005]\u0006 \u0003כל הלין\u0004 \u0005[אלה\u0006\u0005]\u0006 ולא די לו שיאמר \"כשמשון\"? ומשיבים: \u0003צריכי\u0004 \u0005[צריכים\u0006\u0005]\u0006 הדברים להיאמר; \u0003דאי\u0004 \u0005[שאם\u0006\u0005]\u0006 \u0003אמר\u0004 רק \u0003\"הריני כשמשון\", הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]\u0006 על \u0003שמשון אחרינא\u0004 \u0005[אחר\u0006\u0005]\u0006 היתה כוונתו, ואין כאן נדר נזירות כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שמדובר במי שמוסיף \u0003\"כבן מנוח\",\u0004 לומר שכוונתו היתה לשמשון המפורסם, בן מנוח.","\u0003ואי תנא\u0004 \u0005[ואילו שנה\u0006\u0005]\u0006 גם \u0003\"כבן מנוח\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003איכא דמיתקרי הכי\u0004 \u0005[יש מי שנקרא כך\u0006\u0005]\u0006 \"שמשון בן מנוח\", ואין מדובר בשמשון המפורסם, ואין זו קבלת נזירות כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שמדובר במי שמוסיף \u0003\"כבעל דלילה\"\u0004 או \"כמי שעקר דלתות עזה\" \u0003ו\u0004כן \u0003\"כמי שנקרו פלשתים את עיניו\",\u0004 שאז ברור למי הוא מתכוון והרי זה נדר נזירות.","\u0003מה בין נזיר עולם לנזיר שמשון?\u0004 מה ההבדל ביניהם למרות ששניהם הם נזירים כל ימי חייהם? — \u0003נזיר עולם,\u0004 אם \u0003הכביד שערו\u0004 ואיננו יכול לשאת עוד בשיער ארוך זה — הריהו \u0003מיקל\u0004 וחותך מן השיער \u0003בתער, ומביא\u0004 אז לקרבן \u0003שלש בהמות,\u0004 לחטאת, לעולה ולשלמים, כמי שהשלים נזירותו. אלא שנדר הנזירות נמשך וחל עליו מיד לאחר מכן. \u0003ואם נטמא —\u0004 \u0003מביא קרבן טומאה\u0004 שנזיר מביא כאשר נטמא ונטהר מטומאתו.","ואילו \u0003נזיר שמשון\u0004 אם \u0003הכביד שערו —\u0004 \u0003אינו מיקל,\u0004 שאינו מתגלח כלל, \u0003ואם נטמא —\u0004 \u0003אינו מביא קרבן טומאה.\u0004","ותוהים: \u0003נזיר עולם מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמו\u0006\u0005]?\u0006 הרי לא הוזכר במשנה עדיין נזיר עולם, וכיצד באה המשנה לפרש פרטי דברים בהבדל בינו לבין נזיר שמשון? ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה וכך היא שנויה\u0005]:\u0006 \u0003האומר \"הריני נזיר עולם\" —\u0004 \u0003הרי זה נזיר\u0004 לעולם. \u0003מה בין נזיר עולם לנזיר שמשון? נזיר עולם\u0004 אם \u0003הכביד שערו מיקל\u0004 שערו \u0003בתער, ומביא שלש בהמות\u0004 לקרבן, \u0003ואם נטמא —\u0004 \u0003מביא קרבן טומאה. נזיר שמשון, הכביד שערו —\u0004 \u0003אינו מיקל בתער,\u0004"],["\u0003ואינו מביא קרבן טומאה.\u0004","ומעירים: מלשון זו \"ואינו מביא קרבן טומאה\" אפשר לדייק: \u0003קרבן הוא\u0004 ש\u0003לא מייתי\u0004 \u0005[מביא\u0006\u0005]\u0006 נזיר שמשון, \u0003אבל נזירות\u0004 עצמה, \u0003חיילא עליה\u0004 \u0005[חלה עליו\u0006\u0005],\u0006 בכל דיניה, ובכללה שנאסר לו להיטמא למת.","ומעתה נברר: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת מי היא משנתנו\u0005]?\u0006 שהרי אינה \u0003לא\u0004 כדעת \u0003ר' יהודה, ולא\u0004 כדעת \u0003ר' שמעון. דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: נזיר שמשון מותר\u0004 לו לכתחילה \u0003ליטמא למתים, שכן מצינו\u0004 (מצאנו) \u0003בשמשון שנטמא. ר' שמעון אומר: האומר\u0004 ומקבל עליו להיות \u0003\"נזיר שמשון\" —\u0004 \u0003לא אמר כלום, שלא מצינו בשמשון שיצאת נזירות מפיו.\u0004 שהוא עצמו הרי לא נדר להיות נזיר, והדברים שנהג בהם היו על פי דברי המלאך לאמו. ומשום כך סבור ר' שמעון שאין כלל משמעות לנדר שנודר אדם על עצמו להיות \"נזיר שמשון\" ואינו בכלל נדר נזירות.","ומעתה \u0003מני\u0004 \u0005[\u0006כדעת מי היא\u0005]\u0006 משנתנו? \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 כדעת \u0003ר' יהודה —\u0004 \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 \u0003אפילו לכתחילה\u0004 מותר לו להיטמא, \u0003ומתניתין קתני\u0004 \u0005[ומשנתנו שונה\u0006\u0005]\u0006 \u0003\"אם נטמא\",\u0004 שמשמע שדין זה הוא בדיעבד, ולכתחילה אסור. ו\u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 כדעת \u0003ר' שמעון —\u0004 \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 ש\u0003לא חיילא עליה\u0004 \u0005[חלה עליו\u0006\u0005]\u0006 \u0003נזירות כלל!\u0004","ומשיבים: \u0003לעולם\u0004 תאמר שמשנתנו כשיטת \u0003ר' יהודה היא,\u0004 שאף לכתחילה מותר לנזיר שמשון להיטמא למתים, אלא \u0003ואיידי דקתני\u0004 \u0005[ומתוך ששנה\u0006\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר עולם \"אם נטמא\",\u0004 שנזיר עולם ודאי אסור לו להיטמא לכתחילה, \u0003תנא נמי גבי\u0004 \u0005[שנה גם כן אצל\u0006\u0005]\u0006 \u0003נזיר שמשון\u0004 באותה לשון \u0003\"אם נטמא\",\u0004 אף שבאמת מותר לו להיטמא גם לכתחילה.","ומציעים: \u0003לימא בפלוגתא דהני תנאי קמיפלגי\u0004 \u0005[נאמר\u0006 שבמחלוקתם של תנאים אלה חלוקים\u0005]\u0006 ר' יהודה ור' שמעון, \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 הנודר על דבר ואומר \u0003\"הרי\u0004 הוא \u0003עלי כבכור\", ר' יעקב אוסר,\u0004 שלדעתו חל הנדר, וכשם שבכור אסור בהנאה (חוץ מאשר לכהנים), כן אסור הנודר בדבר שנדר בו, \u0003ור' יוסי מתיר,\u0004 משום שקדושת הבכור עצמה אינה תוצאה של נדר והקדשה, אלא הוא קדוש מעצמו, ולכן אינו יכול להחיל על ידו קדושת נדר לדברים אחרים.","\u0003מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 נסבור כי \u0003ר' יהודה סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' יעקב\u0004 ש\u0003אמר:\u0004 על מנת להחיל נדר \u0003לא בעינן\u0004 \u0005[אין אנו צריכים\u0006\u0005]\u0006 שידור דווקא ב\u0003דבר הנידר,\u0004 כלומר, שאדם יכול להחיל איסור על דבר, כשהוא מתפיס בו קדושה של כל דבר האסור, גם אם לא נאסרה הנאתו מחמת נדר. שהרי קדושת הבכור היא מרחם, שעצם לידתו מקדשתו, ואינו נעשה אסור על ידי נדר. וכיוצא בו נאמר כי אף ששמשון עצמו לא נדר בנזיר, יכול אדם להחיל על עצמו נזירות כמו נזירות שמשון. \u0003ור' שמעון סבר לה\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי,\u0004 ש\u0003אמר:\u0004 כדי שיחול הנדר \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005]\u0006 שיתפיס הנודר ב\u0003דבר הנידר,\u0004 ולכן אין משמעות להתפסה בנזירותו של שמשון?","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל\u0006\u0005]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005]\u0006 שיהא הנדר נתפס רק ב\u0003דבר הנידר, ו\u0004אולם לדעת ר' יעקב \u0003שאני\u0004 \u0005[שונה\u0006\u0005]\u0006 הדבר \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003בכור,\u0004 משום \u0003דכתיב ביה\u0004 \u0005[שנאמר בו\u0006\u0005]:\u0006 \u0003\"\u0004איש כי ידור נדר \u0003לה'\"\u0004 (במדבר ל, ג), ולמדו מכאן — \u0003לרבות את הבכור,\u0004 שאף בדבר שהוא לה', כגון בכור שקדוש מרחם, יש צד נדר. ולכן לדעת ר' יעקב הרי הוא כדבר הנידר, ואפשר להתפיס בו נדרים אחרים.","\u0003ור' יוסי אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 לגבי פסוק זה: הכתוב \u0003ההוא,\u0004 שנאמר \u0003\"לה'\" מיבעי ליה\u0004 \u0005[צריך אותו\u0006\u0005]\u0006 לא לרבות בכור אלא \u0003לרבות חטאת ואשם,\u0004 שלמרות שאין אדם יכול לידור אותם על פי רצונו בלבד, אלא כאשר הוא מתחייב בדבר מדין התורה, בכל זאת נחשבים הם כדבר הנידר ומתפיסים בהם.","ושואלים להסבר זה של ר' יוסי: \u0003ומה ראית לרבות חטאת ואשם ולהוציא את הבכור?\u0004 ומשיבים: \u0003מרבה אני חטאת ואשם —\u0004 \u0003שכן מתפיסן בנדר,\u0004 שהרי אין קדושה חלה על הבהמות שתהיינה לחטאת ולאשם אלא כאשר נודר ומפרישן לצורך זה, \u0003ומוציא אני\u0004 מכלל הריבוי \u0003את הבכור, שאין מתפיסו בנדר.\u0004","\u0003ור' יעקב אמר לך\u0004 \u0005[\u0006יכול היה לומר לך\u0005]:\u0006 \u0003בכור נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003מתפיסו בנדר הוא.\u0004 כפי \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003של בית רבינו\u0004 (רבי) \u0003אמרו: מנין ל\u0004מי ש\u0003נולד לו בכור בתוך עדרו שמצוה עליו\u0004 מכל מקום \u0003להקדישו,\u0004 אף שהוא קדוש מעצמו — \u0003שנאמר: \"\u0004כל הבכור אשר יולד בבקרך ובצאנך \u0003הזכר תקדיש\"\u0004 (דברים טו, יט).","\u0003ור' יוסי אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 בתשובה על כך: \u0003נהי\u0004 \u0005[אף\u0006\u0005]\u0006 שאכן יש \u0003מצוה להקדישו,\u0004 ואולם \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003לא מקדיש ליה\u0004 \u0005[אותו\u0006\u0005],\u0006 \u0003מי לא\u0004 \u0005[האם איננו\u0006\u0005]\u0006 \u0003קדוש\u0004 מעצמו? ונמצא שעיקר איסורו לא משום נדר הוא, ולכן אי אפשר להתפיס בו.","ושואלים: והרי לכל הדעות, בין לר' יעקב ובין לר' יוסי, דורשים אנו את המלה \"לה'\" לרבות התפסה בדבר שאיננו נידר, ואם כן \u0003גבי נזיר נמי\u0004 \u0005[גם כן\u0006\u0005],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"\u0004כי יפליא לנדור נדר נזיר להזיר \u0003לה'\"\u0004 (במדבר ו, ב) ומדוע לא נפרש גם כן באותו אופן כי המלה \"לה'\" שבנזירות באה לרבות גם דברים שהם עצמם אינם נידרים, כגון נזירות שמשון!","ודוחים: הכתוב \u0003ההוא,\u0004 \"לה'\", \u0003מיבעי ליה\u0004 \u0005[נצרך לו\u0006\u0005]\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר שמעון הצדיק מימי לא אכלתי אשם נזיר טמא,\u0004 משום שסבר שהנזיר שנטמא מן הסתם מתחרט על עצם נדרו, שהרי צריך לחזור ולשמור שוב כל ימי הנזירות, וכבד עליו הדבר, ומשום כך יש לחשוש שבטל נדר הנזירות מעיקרו על ידי חרטה זו, ונמצא שאינו חייב בקרבן הנזירות כאשר נטמא, והרי זה כמעלה בהמת חולין למזבח. \u0003חוץ מאדם אחד שבא אלי מן הדרום,\u0004 והיה \u0003יפה עינים וטוב רואי\u0004 (יפה תואר), \u0003וקווצותיו\u0004 (קווצות שערות ראשו) \u0003סדורות לו תלתלים. אמרתי לו: בני, מה ראית\u0004 לנדור בנזיר, ועל ידי כך \u0003לשחת שער נאה זה?\u0004 שכן כאשר הנזיר מסיים נזירותו עליו לגלח את שערו.","\u0003אמר לי: רועה הייתי לאבי בעירי והלכתי לשאוב מים מן המעיין, ונסתכלתי בבבואה\u0004 (דמות) \u0003שלי\u0004 במים, \u0003ופחז\u0004 (גאה) \u0003יצרי עלי, וביקש לטורדני מן העולם,\u0004 שראיתי כמה אני יפה. \u0003אמרתי לו,\u0004 כלומר, לעצמי: \u0003ריקה! מפני מה אתה מתגאה בעולם שאינו שלך, ש\u0004הרי \u0003סופך\u0004 לכשתמות \u0003להיות רמה ותולעה? העבודה\u0004 (נשבע אני בעבודת המקדש) \u0003שאגלחך לשמים\u0004 בנזירות.","וסיפר שמעון הצדיק: כששמעתי דברים אלה \u0003עמדתי ונשקתיו על ראשו, אמרתי לו: כמותך ירבו נזירים בישראל\u0004 שכוונתם לטובה, ואף אם נטמאים — אינם מתחרטים על נזירותם, \u0003עליך הכתוב אומר: \"איש\u0004 או אשה \u0003כי יפלא לנדר נדר נזיר להזיר לה'\"\u0004 (במדבר ו, ב), שנזירות זו איננה מחמת כעס או הקנטה, אלא היא כל כולה בכוונה לה'. ואם כן \"לה'\" בפסוק זה פירושו — שכוונתו לשם שמים, ואין ללמוד מכאן לנזירות שמשון.","ושואלים לגופם של דברים: \u0003ו\u0004האם \u0003שמשון לאו\u0004 \u0005[לא\u0006\u0005]\u0006 \u0003נזיר הוה\u0004 \u0005[היה\u0006\u0005]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006\u0005]:\u0006 \u0003\"כי נזיר אלהים יהיה הנער מן הבטן\"\u0004 (שופטים יג, ה)! ומשיבים: \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003מלאך הוא דקאמר\u0004 \u0005[שאמר\u0006\u0005]\u0006 את הדברים, אבל שמשון עצמו לא קיבל על עצמו נדר נזירות.","ושואלים: \u0003ומנלן דאיטמי\u0004 \u0005[ומנין לנו שנטמא\u0006\u0005]\u0006 שמשון \u0003למתים? אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה שנאמר\u0005]\u0006 \u0003\"\u0004ויאמר שמשון... \u0003בלחי החמור הכיתי אלף איש\"\u0004 (שופטים טו, טז) — \u0003דילמא גרויי גרי בהו\u0004 \u0005[שמא היכה אותם\u0006\u0005]\u0006 בלחי החמור \u0003ו\u0004אולם \u0003לא נגע בהו\u0004 \u0005[בהם\u0006\u0005]\u0006 ולא נטמא!","\u0003אלא מהכא\u0004 \u0005[מכאן\u0006\u0005]:\u0006 \u0003\"ויך מהם שלשים איש ויקח את חליצותם\"\u0004 (שופטים יד, יט), שכיון שפשט את בגדיהם של מתים אלה ודאי נגע בהם. ושואלים: \u0003דילמא אשלחינון ברישא והדר קטלינן\u0004 \u0005[שמא הפשיט אותם תחילה ואחר כך הרג אותם\u0006\u0005]?\u0006 ומשיבים: \u0003\"ויך... ויקח\" כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 לפי הסדר הזה, שקודם היכם = הרגם, ואחר כך לקח מהם את בגדיהם.","ומקשים: ועדיין כיצד מוכיחים מכאן שנטמא למתים? \u0003ודילמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 \u0003גוססין שוינן\u0004 \u0005[עשה אותם\u0006\u0005],\u0006 שלא המיתם לגמרי אלא היכה אותם מכות מוות, ופשט את בגדיהם בעודם גוססים, ואם כן לא נטמא למתים! \u0003אלא\u0004 יש לומר: \u0003גמרא גמירי לה\u0004 \u0005[במסורת לומדים\u0006 אנו אותה\u0005]\u0006 שהיה שמשון נטמא למתים.","לגופה של ההלכה ששנינו במשנה מבררים: \u0003ונזיר עולם היכא כתיב\u0004 \u0005[היכן\u0006 הוא כתוב\u0005]?\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003רבי אומר: אבשלום נזיר עולם היה, שנאמר: \"ויהי מקץ ארבעים שנה ויאמר אבשלום אל המלך אלכה נא ואשלם את נדרי אשר נדרתי לה' בחברון\"\u0004 (שמואל ב טו, ז), \u0003ומגלח\u0004 היה את שערו \u0003אחד לשנים עשר חדש, שנאמר:\u0004 \"ובגלחו את ראשו \u0003ויהי מקץ ימים לימים\u0004 אשר יגלח כי כבד עליו וגלחו\" (שופטים יד, כו)."],["\u0003ויליף\u0004 \u0005[ולמד\u0006\u0005]\u0006 רבי בגזירה שוה \u0003\"ימים\" \"ימים\" מבתי ערי חומה\u0004 (\"ימים תהיה גאולתו\". ויקרא כה, כט) \u0003מה התם\u0004 \u0005[שם\u0006\u0005]\u0006 \"ימים\" פירושו \u0003שנים עשר חדש,\u0004 כמפורש אחר כך \"עד מלאת לו שנה תמימה\" ( ויקרא כה, ל) — \u0003אף כאן\u0004 זמן נזירות אבשלום שנאמר בה \"ימים\", היתה \u0003שנים עשר חדש.\u0004","\u0003ר' נהוראי אומר:\u0004 אבשלום היה \u0003מגלח אחת לשלשים יום. ר' יוסי אומר: מגלח\u0004 היה \u0003מערב שבת לערב שבת, שכן מצינו\u0004 \u0005[מצאנו\u0006\u0005]\u0006 רואים אנו \u0003בבני מלכים שמגלחים מערב שבת לערב שבת.\u0004","ותמהים: כפי שאמרנו לעיל \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003רבי —\u0004 \u0003יליף\u0004 \u0005[למד\u0006\u0005]\u0006 הוא \u0003מבתי ערי חומה. והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003רבי\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר: אין \"ימים\" פחותין משנים,\u0004 שכך הוא פוסק שאין אדם יכול לגאול את הבית לפני שהיה יומיים ברשות הקונה. ואם כן משמע שהוא מפרש \"ימים\" זה האמור בדין בתי ערי חומה לא במשמעות שנה, וכיצד למד בגזירה שווה מבתי ערי חומה ש\"ימים\" שבנזירות אבשלום הם שנים עשר חודש!","ומשיבים: \u0003האי\u0004 \u0005[זו\u0006\u0005]\u0006 \u0003גזירה שוה משום כובד גמיר\u0004 \u0005[למד\u0006\u0005]\u0006 אותה, שהרי נאמר בכתוב שהיה אבשלום גוזר שערו כשהיה השיער מכביד עליו, \u0003ובשני ימים ליכא\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003כובד\u0004 שיער, ונמצא שיש להבין ימים לענין זה כמובנו הפשוט, שנה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור\u0006\u0005]\u0006 כי \"ימים\" הוא \u0003שתי שנים,\u0004 כמו \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 \u0003\"ויהי מקץ שנתים ימים\"\u0004 (בראשית מא, א)?! ודוחים: \u0003דנין \"ימים\" שאין עמהן שנים,\u0004 שנאמר באבשלום רק \"ימים\", \u0003מ\"ימים\" שאין עמהן שנים\u0004 כנאמר בבתי ערי חומה, \u0003ואל יוכיח\u0004 \"ימים\" \u0003זה שיש עמו\u0004 גם מספר \u0003שנים\u0004 (\"שנתיים\").","ושואלים: \u0003ואימא\u0004 \u0005[ואמור\u0006\u0005]\u0006 ש\"ימים\", הוא \u0003שלשים יום,\u0004 כמו \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"עד חדש ימים\"\u0004 (במדבר יא, כ)! ודוחים: \u0003דנין \"ימים\" שאין עמהם חדשים מ\"ימים\" שאין עמהם חדשים, ואל יוכיח זה שיש עמו חדשים.\u0004","ושואלים: \u0003ואימא מהכא\u0004 \u0005[ואמור\u0006 שילמד רבי, ובאופן שונה, מכאן\u0005],\u0006 שנאמר: \u0003\"מימים ימימה\u0004 תלכנה בנות ישראל לתנות לבת יפתח הגלעדי ארבעת ימים בשנה\u0003\"\u0004 (שופטים יא, מ), ומבינים שהכוונה היא שארבע פעמים בשנה, ובכל פעם — יום אחד, היו מבכות אותה, ונמצא ש\"מימים ימימה\" מובנו: אחת לשלושה חודשים! ודוחים: \u0003דנין \"ימים\" מ\"ימים\", ואין דנין \"ימים\" מ\"ימימה\",\u0004 שאין המילים שוות.","ומקשים: \u0003ומאי נפקא מינה\u0004 \u0005[ומה יוצא מזה,\u0006 מה זה משנה\u0005],\u0006 הלא אפילו כשאין המילים ממש שוות למדים אנו גזירה שווה, \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם מבית מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"ושב הכהן\"\u0004 ונאמר \u0003\"ובא הכהן\"\u0004 (ויקרא יד, לט ושם מד) — \u0003זו היא שיבה זו היא ביאה,\u0004 ולמדים גזירה שווה זו מזו. הרי שאפילו כאשר המילים אינן דומות כלל אלא תוכנן זהה אפשר ללמוד גזירה שווה, וכל שכן כאשר יש שינוי קל במילים!","ומשיבים: \u0003הני מילי היכא דליכא דדמי ליה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא היכן שאין מקרא אחר שדומה לו\u0005]\u0006 בדיוק, \u0003אבל היכא דאיכא דדמי ליה\u0004 \u0005[היכן שיש\u0006 מקרא אחר הדומה לו\u0005] —\u0006 \u0003מדדמי ליה ילפינן\u0004 \u0005[מהדומה לו למדים אנו\u0006\u0005],\u0006 ולכן עדיף ללמוד מן האמור בבתי ערי חומה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006\u0005]\u0006 תירוץ אחר לדחות את האפשרות ללמוד \"מימים ימימה\", משום שלא ברור הוא מה שיעור הזמנים האמור ב\"ימים ימימה\". שכן, \u0003מנא ידעינן דכל תלתא ירחין חד זימנא\u0004 \u0005[מנין אנו יודעים שכל שלושה חודשים פעם אחת\u0006\u0005]\u0006 לפי חלוקה קבועה היו עולות לתנות לבת יפתח? \u0003דילמא ארבעה זימני בשתא\u0004 \u0005[שמא ארבע פעמים בשנה\u0006\u0005],\u0006 שאין להם קביעות של זמן, \u0003אי נמי\u0004 \u0005[או גם כן\u0006\u0005]\u0006 \u0003ארבעה ירחין חד זימנא\u0004 \u0005[ארבעה חודשים פעם אחת\u0006\u0005],\u0006 \u0003תרין ירחין בחד זימנא\u0004 \u0005[שני חודשים פעם אחת\u0006\u0005]\u0006 ושוב לאחר ארבעה חודשים, ואחר כך לאחר חודשיים!","ועל מה ששנינו בברייתא: \u0003ר' נהוראי אומר:\u0004 אבשלום \u0003מגלח\u0004 היה \u0003אחת לשלשים יום,\u0004 מסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מניין למד כן\u0005]?\u0006 כמו \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003כהנים\u0004 שהם צריכים לגלח אחת לשלושים יום \u0003משום דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003כובד\u0004 שיער בשיער שגדל שלושים יום, \u0003הכא נמי איכא\u0004 \u0005[כאן,\u0006 באבשלום, גם כן יש\u0005]\u0006 \u0003כובד\u0004 וכפי שנאמר \"כי כבד עליו וגלחו\" (שמואל ב יד, כו).","ועוד שנינו בברייתא, \u0003ר' יוסי אומר: מגלח\u0004 היה אבשלום \u0003מערב שבת לערב שבת\u0004 שכן מצינו בבני מלכים שמגלחים מערב שבת לערב שבת. ושואלים: אם כן \u0003מאי איכא ביניה\u0004 \u0005[מה,\u0006 איזה הבדל, יש בינו\u0005],\u0006 בין אבשלום הנזיר, \u0003ל\u0004בין \u0003שאר אחוהי\u0004 \u0005[אחיו\u0006\u0005]\u0006 בני דוד המלך, שהרי אף הם — כבני מלכים — גילחו מערב שבת לערב שבת!","ומשיבים: ההבדל ביניהם ניכר במקרה של \u0003יום טוב שחל להיות באמצע שבת\u0004 (השבוע) \u0003דאחוהי מגלחין\u0004 \u0005[שאחיו\u0006 היו מגלחים\u0005]\u0006 לכבוד יום טוב, \u0003הוא לא מגלח. אי נמי\u0004 \u0005[או גם כן\u0006\u0005]\u0006 הבדל נוסף ביניהם: \u0003לגלוחי מן צפרא דמעלי שבתא\u0004 \u0005[לגלח מבוקרו של ערב שבת\u0006\u0005],\u0006 \u0003אחוהי מגלחין\u0004 \u0005[אחיו מגלחים\u0006\u0005],\u0006 ואילו \u0003איהו\u0004 \u0005[הוא\u0006\u0005]\u0006 \u0003לא מגלח עד פניא\u0004 \u0005[הערב\u0006\u0005].\u0006","אגב הזכרת פסוק זה באבשלום, שואלים: \u0003הני\u0004 \u0005[אותן\u0006\u0005]\u0006 \u0003ארבעים שנה\u0004 שהוזכרו שם (\"ויהי מקץ ארבעים שנה ויאמר אבשלום אל המלך\" וכו'. שמואל ב טו, ז) \u0003מאי עבידתייהו\u0004 \u0005[מה מעשיהן,\u0006 מה עניינן\u0005],\u0006 למה הן מתייחסות? \u0003ר' נהוראי אומר משום\u0004 (משמו של) \u0003ר' יהושע: לקץ ארבעים שנה ששאלו להן\u0004 בני ישראל \u0003מלך\u0004 בימי שמואל. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אותה שנה ששאלו להן מלך היא שנת עשר לשמואל הרמתי,\u0004 ומכאן אפשר להגיע בחשבון השנים שמרד אבשלום היה ארבעים שנה לאחר מכן.","\u0003סתם נזירות\u0004 שלא קבע הנוזר זמן מוגדר של נזירות, היא של \u0003שלשים יום.\u0004","שואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו\u0006\u0005]\u0006 שזהו זמנה של נזירות סתם? \u0003אמר רב מתנא: אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 בנזיר: \u0003\"קדש יהיה\"\u0004 (במדבר ו, ה) \u0003\"יהיה\" בגמטריא תלתין הוו\u0004 \u0005[שלושים הם\u0006\u0005],\u0006 והרי זה רמז שהנזיר יהיה נזיר שלושים יום.","ואילו \u0003בר פדא אמר:\u0004 מספר ימי נזירות סתם הוא עשרים ותשעה, \u0003כנגד\u0004 מספר הביטויים \u0003\"נזיר\" \"נזרו\"\u0004 והדומים להם \u0003האמורים בתורה\u0004 בפרשת נזירות, שהם \u0003שלשים חסר אחת.\u0004","ושואלים: \u0003ורב מתנא נמי נילף\u0004 \u0005[גם כן\u0006 שילמד\u0005]\u0006 \u0003מ\u0004מנין \u0003\"נזיר\" \"נזרו\"\u0004 כבר פדא שסתם נזירות היא בת עשרים ותשעה יום!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 רב מתנא: אין למדים מהם כיון ש\u0003ההוא לדרשה,\u0004 שכל אחד מאלה בא לדרשה מיוחדת, כגון \u0003\"מיין ושכר יזיר\"\u0004 (במדבר ו, ג) — \u0003לאסור יין מצוה כיין רשות,\u0004 ומה שנאמר \u0003\"כי יפלא לנדר נדר נזיר להזיר\"\u0004 (במדבר ו, ב) — \u0003מלמד שהנזירות חלה על נזירות,\u0004 שאם אדם נדר להיות נזיר היום, ונדר שוב להיות נזיר היום — חלה עליו חובת נזירות נוספת על הנזירות הראשונה."],["\u0003ובר פדא אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך:\u0004 אף שיש כמה דרשות בפסוקים אלה, מכל מקום, \u0003ליכא חד מינהון דלאו לדרשא\u0004 \u0005[\u0006האם אין אחד מהם שאינו בא לדרשה\u0005]?\u0006 שהרי אין דרשות על כל מקום שנזכר בו לשון \"נזיר\" או \"להזיר\". \u0003אלא מדההוא\u0004 \u0005[מ\u0006כיון שאותו\u0005]\u0006 מקום שנזכר \"נזיר\" אינו לדרשה אלא \u0003למניינא\u0004 \u0005[למנין\u0006\u0005],\u0006 \u0003כולהו נמי למניינא\u0004 \u0005[כולם גם כן למנין\u0006\u0005]\u0006 נאמרו, מלבד הדרשה הנדרשת בהם, כל אחד לעניינו.","מכאן באים לדון בשיטותיהם של רב מתנא ובר פדא, ולברר את הדברים לפי המשנה והברייתות.\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003סתם נזירות שלשים יום. בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004שיטת \u0003רב מתנא\u0004 שלמדים ממה שנאמר \"יהיה\" שהוא מנין שלושים — \u0003ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 שאכן סתם נזירות שלושים יום, \u0003אלא לבר פדא קשיא\u0004 \u0005[קשה\u0006\u0005],\u0006 שהרי לדעתו צריך שתהיה סתם נזירות רק עשרים ותשעה יום!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך בר פדא: איידי דאיכא\u0004 \u0005[מתוך שיש\u0006\u0005]\u0006 בנזירות \u0003יום תלתין\u0004 \u0005[שלושים\u0006\u0005]\u0006 ש\u0003מגלח\u0004 בו \u0003ומביא קרבנותיו,\u0004 ואף באותו יום שלושים אסור הוא באיסורי נזירותו עד שיביא את קרבנותיו, \u0003משום הכי\u0004 \u0005[כך\u0006\u0005]\u0006 \u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003שלשים,\u0004 אבל ימי איסור הנזירות בעיקרם אינם אלא עשרים ותשעה.","ושואלים עוד: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שאמר \"הריני נזיר\" —\u0004 \u0003מגלח יום שלשים ואחד. בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004שיטת \u0003רב מתנא ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 שצריך להשלים שלושים יום לנזירות ורק לאחר מכן מגלח, \u0003אלא ל\u0004דעת \u0003בר פדא קשיא\u0004 \u0005[קשה\u0006\u0005]\u0006 מדוע לא יגלח ביום שלושים!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך בר פדא\u0004 כמענה לשאלה: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את סופה\u0005]\u0006 של משנה זו: \u0003אם גילח ליום שלשים —\u0004 \u0003יצא,\u0004 משמע שהנזירות עצמה היא רק בת עשרים ותשעה יום. \u0003אלא סיפא מסייעא ליה\u0004 \u0005[סופה\u0006 של אותה משנה ודאי מסייע לו\u0005],\u0006 \u0003רישא\u0004 \u0005[ראשה,\u0006 תחילתה\u0005] —\u0006 \u0003נעשה כאומר \"שלימין\",\u0004 שהרי אם אומר שהוא רוצה לנזור שלושים יום שלמים — הריהו מגלח ביום שלושים ואחד, ומשום כך אמרו חכמים שלכתחילה, אף בסתם, לא יגלח לפני שסיים שלושים יום.","ושואלים: \u0003ולרב מתנא קשיא סיפא\u0004 \u0005[קשה הסוף\u0006\u0005]\u0006 של המשנה האומר שאם גילח ביום שלושים יצא. והרי, לשיטתו, עדיין לא הסתיימו ימי הנזירות! ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 שמחשיבים אנו \u0003מקצת היום ככולו,\u0004 ולכן אף שנזירות היא שלושים יום, כיון שכבר התחיל יום שלושים, הרי זה נחשב לו כאילו סיים שלושים יום, ומשום כך אם גילח בו ביום — יצא.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 האומר \u0003\"הריני נזיר שלשים יום\", אם גילח יום שלשים —\u0004 \u0003לא יצא,\u0004 וקשה לבר פדא! ומשיבים: מכאן אין ראיה, שכן אפשר לומר כי מדובר \u0003באומר\u0004 \u0003\"\u0004שלושים יום \u0003שלימין\",\u0004 שאז בוודאי אינו יוצא בגילוח ביום שלושים.","ושואלים עוד: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שנזר שתי נזירות\u0004 — \u0003מגלח את הראשונה יום שלשים ואחד, והשניה ליום ששים ואחד. בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004שיטת \u0003רב מתנא —\u0004 \u0003ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שנזירות ראשונה מגלח אחר שלושים יום שלימים — ביום שלושים ואחד, ונזירות שניה מתחילה בו ביום, ונמצא שמגלח ביום השלושים ואחד לנזירותו השניה."],["\u0003אלא לבר פדא קשיא\u0004 \u0005[קשה\u0006\u0005]\u0006 מדוע לא יגלח את הראשונה כבר ביום שלושים ואת השניה כבר ביום שישים!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 \u0003בר פדא: אימא סיפא\u0004 \u0005[אמור\u0006 את סוף\u0005]\u0006 המשנה: \u0003ואם גילח את הראשונה ליום שלשים —\u0004 \u0003מגלח את השניה ליום ששים,\u0004 משמע שמעיקר הדין אין נזירות אלא עשרים ותשעה יום. \u0003אלא, סיפא\u0004 \u0005[סוף\u0006\u0005]\u0006 המשנה \u0003מסייעא ליה\u0004 \u0005[מסייעת לו\u0006\u0005]\u0006 לשיטתו, ואילו \u0003רישא\u0004 \u0005[ראש,\u0006 תחילת\u0005]\u0006 המשנה ששנינו שמגלח בשלושים ואחד והשניה בשישים ואחד — \u0003באומר\u0004 שתהיה הנזירות שלושים יום \u0003שלימים.\u0004","ושואלים מצד שני: \u0003ולרב מתנא קשיא סיפא\u0004 \u0005[קשה סוף\u0006\u0005]\u0006 המשנה! \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך רב מתנא כדקתני סיפא\u0004 \u0005[כפי ששנה\u0006 בסופה\u0005]:\u0006 \u0003יום שלשים עולה\u0004 (נחשב) \u0003לכאן ולכאן,\u0004 כלומר, לסוף נזירות ראשונה ולתחילת השניה.","ומקשים: \u0003מאי היא\u0004 \u0005[מה הוא\u0006\u0005]\u0006 החידוש שבדבר — לומר ש\u0003מקצת היום ככולו? הא הרי\u0004 כבר \u0003אמרה\u0004 לאותו חידוש \u0003חדא זימנא\u0004 \u0005[פעם אחת\u0006\u0005],\u0006 כפי שביארנו את הדברים קודם! ומשיבים: בכל זאת יש בכך חידוש, \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006\u0005]\u0006 שמקצת היום ככולו, נאמרו דווקא \u0003לענין חדא נזירות\u0004 \u0005[נזירות אחת\u0006\u0005]\u0006 שאז מחשיבים מקצת היום ככולו, \u0003אבל לשתי נזירות\u0004 שאותו יום ייחשב למנין ימי שתי נזירויות, לאחת — כסופה, ולאחת — כתחילתה, ובשתיהן ייחשב מקצת היום ככולו — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שמקצת היום ככולו בכל אופן, ועולה יום שלושים כיום שלם גם לשתי הנזירויות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם גילח יום ששים\u0004 \u0003חסר אחד —\u0004 \u0003יצא,\u0004 לפי \u0003שיום שלשים עולה לו מן המנין. בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003לרב מתנא ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 שהרי מפורש הטעם, שמקצת היום עולה ככולו. \u0003אלא לבר פדא למה לי\u0004 לומר טעם זה? \u0003הא אמר\u0004 \u0005[הרי\u0006 הוא אומר\u0005]\u0006 כשיטה שעיקר נזירות הוא \u0003שלשים חסר אחד!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 בר פדא: \u0003אנא נמי אהא סמכי\u0004 \u0005[אני גם כן על זה אני סומך\u0006\u0005],\u0006 שמכאן אני מוכיח שסתם נזירות היא עשרים ותשעה יום.","ועוד שואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שאמר \"הריני נזיר\",\u0004 אם \u0003נטמא יום שלשים —\u0004 \u0003סותר\u0004 (שובר) \u0003את הכל\u0004 כאילו נטמא בתחילת ימי נזירותו, וכל הנזירות בטילה, וצריך לחזור ולהיות נזיר שלושים יום אחרים. ועתה \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004שיטת \u0003רב מתנא ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שהרי הוא עדיין בתוך נזירותו, \u0003אלא לבר פדא קשיא\u0004 \u0005[קשה\u0006\u0005],\u0006 שהרי לדעתו יום שלושים הוא כבר אחרי זמן הנזירות, והנטמא לאחר שמלאו ימי נזירותו — אינו צריך לסתור את נזירותו!"],["\u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 \u0003בר פדא: אימא סיפא\u0004 \u0005[אמור\u0006 את סוף\u0005]\u0006 המשנה, \u0003ר' אליעזר אומר: אינו סותר\u0004 (שובר) ומונה מחדש עוד \u0003אלא שבעה\u0004 ימים של נזירות. \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006\u0005]\u0006 לומר כי \u0003שלשים\u0004 יום \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005]\u0006 לנזירות, אם כן \u0003נסתור כולהו\u0004 \u0005[שיסתור\u0006 את כל הימים כולם\u0005],\u0006 שהרי זהו עדיין בתוך ימי נזירותו. ומכאן שסתם נזירות היא בת עשרים ותשעה יום!","ודוחים: מכאן אין ראיה, שכן \u0003קסבר\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003ר' אליעזר: מקצת היום ככולו,\u0004 וכאילו כבר סיים את הנזירות בתחילת יום השלושים.","ובעיקר שיטתו של ר' אליעזר מתקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 האומר \u0003\"הריני נזיר מאה יום\", נטמא\u0004 ב\u0003יום מאה —\u0004 \u0003סותר את הכל\u0004 ולאחר שמקריב קרבן נזיר טמא חוזר ומונה מחדש מאה ימי נזירות. \u0003ר' אליעזר אומר: אינו סותר\u0004 ומונה מחדש \u0003אלא שלשים יום\u0004 בלבד. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר ש\u0003סבר ר' אליעזר\u0004 ש\u0003מקצת היום ככולו —\u0004 אם כן \u0003נסתור\u0004 \u0005[שיסתור\u0006\u0005]\u0006 רק \u0003שבעה\u0004 ימים, שייחשב לו כאילו נטמא לאחר שהשלים את ימי נזירותו, \u0003ואי לא סבר\u0004 \u0005[ואם אינו סבור\u0006\u0005]\u0006 ש\u0003מקצת היום ככולו —\u0004 \u0003ליסתור כולהו\u0004 \u0005[שיסתור\u0006 את כולם\u0005],\u0006 שהרי נטמא בתוך זמן נזירותו!","ומשיבים: \u0003לעולם לא אמרינן\u0004 \u0005[אין אנו אומרים\u0006\u0005]\u0006 \u0003מקצת היום ככולו.\u0004 ומקשים: \u0003אי הכי ליסתור כולהו\u0004 \u0005[אם כך שיסתור\u0006 את כל הימים כולם\u0005]!\u0006 \u0003אמר ריש לקיש: היינו טעמא\u0004 \u0005[זהו הטעם\u0006\u0005]\u0006 של \u0003ר' אליעזר:\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"\u0004ו\u0003זאת תורת הנזיר ביום מלאת ימי נזרו\"\u0004 (במדבר ו, יג), \u0003התורה אמרה:\u0004 אם \u0003נטמא ביום מלאת,\u0004 בדיוק ביום שנשלמה בו הנזירות — \u0003תן לו תורת נזיר\u0004 סתם, שיסתור רק כדי נזירות אחת, וסתם נזירות היא בת שלושים יום.","עד כאן הדיונים בעיקרי שיטות רב מתנא ובר פדא. ומעתה מציעים, \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 שנחלקו כמחלוקתם של תנאים\u0005],\u0006 ששנינו בברייתא: נאמר בפרשת נזיר \u0003\"עד מלאת הימים\u0004 אשר יזיר לה' קדוש יהיה גדל פרע שער ראשו\u0003\"\u0004(במדבר ו, ה),","\u0003שומעני\u0004 (שומע אני) מתוך זה ש\u0003מיעוט \"ימים\" שנים,\u0004 שבכך יצא חובת נזירות — \u0003תלמוד לומר \"קדש יהיה גדל פרע\u0004 שער ראשו\u0003\"\u0004 (במדבר ו, ה) — \u0003אין גידול שער פחות משלשים\u0004 יום, אלו \u0003דברי ר' יאשיה.\u0004","\u0003ר' יונתן אומר: אינו צריך\u0004 לראיה זו, ש\u0003הרי הוא אומר \"עד מלאת הימים\" אי אלו הן ימים שצריכין למלאת —\u0004 \u0003הוי אומר שלשים\u0004 כי זמן חודש הלבנה הוא עשרים ותשעה יום וחצי, וכדי למלא את הימים משלימים את החודש לשלושים יום. ונמצא שרק בתקופה של חודש יש משמעות של \"מלאת הימים\".","ולענייננו, \u0003מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 נאמר ש\u0003רב מתנא\u0004 הוא ש\u0003אמר כ\u0004דעת \u0003ר' יאשיה,\u0004 שהראיה היא מהפסוק \"קדוש יהיה גדל פרע\", ולכן נזירות היא בת שלושים יום, \u0003ובר פדא\u0004 הוא ש\u0003אמר כ\u0004דעת \u0003ר' יונתן\u0004 שלמדים מימי החודש שהם עשרים ותשעה, ולכן אף נזירות היא בת עשרים ותשעה יום?","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 \u0003רב מתנא:\u0004 אין מחלוקת בדבר, שכן \u0003כולי עלמא\u0004 \u0005[לדעת הכל\u0006\u0005]\u0006 \u0003שלשים\u0004 יום \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005],\u0006 \u0003והכא\u0004 \u0005[וכאן\u0006\u0005]\u0006 \u0003ב\u0004שאלה אחרת: האם \u0003\"עד\"\u0004 משמעו \u0003ועד בכלל,\u0004 שהתאריך שנאמר בו \"עד\" נמצא בכלל מנין זה, או לא, בכך \u0003פליגי\u0004 \u0005[נחלקו\u0006\u0005];\u0006 \u0003ר' יאשיה סבר\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003\"עד\u0004 מלאת הימים \u0003\"\u0004\u0003ולא עד בכלל\u0004 ולכן אין יום שלושים נכלל, ואם כן אין להוכיח מן הכתוב שנזירות היא בת שלושים יום, ונמצא שיש צורך ללמוד מ\"גדל פרע שער ראשו\". \u0003ו\u0004אילו \u0003ר' יונתן סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003\"עד\" ועד בכלל,\u0004 ולכן הוא לומד את ההלכה שנזירות היא בת שלושים יום מלשון הכתוב במישרין. כיון שהוזכרה ברייתא זו, מפרשים את האמור בה.","\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 ר' יונתן: \u0003אי אלו הן ימים שצריכין למלאות —\u0004 \u0003הוי אומר שלשים.\u0004 ושואלים: מנין שמדובר פה בחודש, שיש בו שלושים יום? \u0003ואימא\u0004 \u0005[ואמור\u0006\u0005]\u0006 \u0003שבת\u0004 (שבוע) שגם הוא נשלם ביום השבת הבא לאחר ששת ימי החול! ודוחים: \u0003שבת\u0004 (שבוע) \u0003מי איכא חסירותא\u0004 \u0005[האם יש\u0006 בו צד חסרון\u0005]\u0006 שיש לומר בו שכאשר באה שבת הרי הוא שבוע מלא? אלא דווקא בחודשים יש חסרים ומלאים, ולכן יש מקום לדבר על \"מלאת הימים\"."],["\u0003ואימא\u0004 \u0005[ואמור\u0006\u0005]\u0006 שהכוונה ל\u0003שנה?\u0004 שהרי אף בשנים יש חסירה ומליאה! ודוחים: \u0003מי מנינן ליומי\u0004 \u0005[האם אנו מונים\u0006 את השנה לימים\u0005]?\u0006 \u0003והא רבנן דקיסרי אמרי\u0004 \u0005[והרי חכמי קיסרי אומרים\u0006\u0005]:\u0006 \u0003מנין שאין מונין ימים לשנים,\u0004 אלא מחשבים את השנים על פי חודשים — \u0003שנאמר: \"לחדשי השנה\"\u0004 (שמות יב, ב), לומר לנו: \u0003חדשים מחשבין לשנים ולא ימים לשנים,\u0004 ומשום כך מה שיש בו מילוי של ימים — הוא חודש בלבד.","\u0003אמר\u0004 אדם: \u0003\"הריני נזיר אחת גדולה\",\u0004 או שאמר: \u0003\"הריני נזיר אחת קטנה\",\u0004 או \u0003אפילו\u0004 אמר: \u0003\"\u0004הריני נזיר \u0003מכאן ועד סוף העולם\",\u0004 בכל המקרים הללו — הריהו \u0003נזיר שלשים יום.\u0004","שנינו במשנה שאף אם נדר \"הריני נזיר מכאן ועד סוף העולם\" — הריהו נזיר שלושים יום. ושואלים: \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 יהיה נזיר רק שלושים יום? \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 במפורש \u0003\"מכאן ועד סוף העולם\" קאמר\u0004 \u0005[הוא אומר]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך יש להבין את דבריו: \u0003אריכא\u0004 \u0005[ארוך\u0006\u0005]\u0006 \u0003לי הדא מילתא\u0004 \u0005[דבר זה]\u0006 של נזירות, בגלל הקשיים שבו, \u0003כמכאן ועד סוף העולם.\u0004","על כך מקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 האומר \u0003\"הריני נזיר מכאן ועד מקום פלוני\"\u0004 — \u0003אומדים כמה ימים\u0004 של הליכה יש \u0003מכאן ועד\u0004 אותו \u0003מקום פלוני,\u0004 ואם היה זה מרחק הליכה של \u0003פחות משלשים יום\u0004 — הרי הוא \u0003נזיר שלשים יום,\u0004 שאין נזירות בפחות מכן. \u0003ואם לאו,\u0004 \u0005[לא\u0006\u0005]\u0006 שהוא מרחק הליכה יותר משלושים יום — הרי הוא \u0003נזיר כמנין הימים\u0004 שיש ללכת עד אותו מקום פלוני. \u0003ואימא הכא נמי\u0004 \u0005[ונאמר גם כן כאן\u0006 באותה משנה\u0005]\u0006 בפירוש דבריו: \u0003אריכא\u0004 \u0005[ארוך\u0006\u0005]\u0006 \u0003לי הא מילתא\u0004 \u0005[דבר זה\u0006\u0005]\u0006 של נזירות כאילו הייתי צריך ללכת \u0003מכאן ועד מקום פלוני,\u0004 אך כל כוונתו היתה לנזירות של שלושים יום בלבד!","\u0003אמר רבא:\u0004 באותה משנה מדובר במי \u0003שהחזיק בדרך,\u0004 שהחל ללכת כבר באותה דרך, ונראה שכוונתו היתה שמקבל על עצמו נזירות עד שיגיע למקום פלוני. ושואלים: מדוע מונים את ימי הנזירות לפי מנין הימים שיש ללכת עד שם? \u0003וליהוי\u0004 \u0005[ושתהיה\u0006\u0005]\u0006 \u0003כל פרסה\u0004 (מידת מרחק) \u0003ופרסה\u0004 נחשבת כיחידה לענין זה, וימנה מספר נזירויות כמנין הפרסות! \u0003אמר רב פפא:\u0004 מדובר במשנה \u0003באתרא\u0004 \u0005[במקום\u0006\u0005]\u0006 ש\u0003לא מני פרסי\u0004 \u0005[מונים פרסות\u0006\u0005].\u0006","ושואלים עוד: \u0003וליהוי\u0004 \u0005[ושתהא\u0006\u0005]\u0006 \u0003כל אוונא ואוונא\u0004 \u0005[תחנה ותחנה\u0006\u0005]\u0006 בה לנים אנשים בסוף כל יום הליכה נחשבת כיחידה לעצמה, ולפי מנין זה יימנו מספר נזירויות ולא מספר ימים! \u0003מי\u0004 \u0005[האם\u0006\u0005]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 האומר \u0003\"הריני נזיר כעפר הארץ\",\u0004 או שאמר \u0003\"\u0004הריני נזיר \u0003כשער ראשי\",\u0004 או \u0003\"כחול הים\" —\u0004 \u0003הרי זה נזיר עולם,\u0004 שכן מניחים אנו שקיבל על עצמו נזירויות כמנין שערותיו או כגרגרי העפר והחול, \u0003ומגלח אחד לשלשים יום.\u0004 משמע שאנו דנים כל פרט מאלה כקבלת נזירות לעצמה!","ודוחים: \u0003כל מילתא דאית ביה קיצותא\u0004 \u0005[דבר שיש בו קיצבה\u0006\u0005]\u0006 התנא \u0003לא קתני\u0004 \u0005[שונה\u0006\u0005]\u0006 בדין זה. כי כאשר מקבל עליו נדר נזירות בדבר שאין בו מנין ברור (כמו עפר הארץ) אין לומר שמקבל עליו נזירות אחת שימיה כמנין גרגרי העפר — שהרי אינו יודע מה מספרם. מה שאין כן כשקובע בדבר קצוב, כמו מהלך למקום מסויים, שאז יש להניח שכוונתו היתה למספר ימים קצוב.","\u0003והתניא\u0004 \u0005[ו\u0006אכן כן שנינו בברייתא\u0005],\u0006 האומר: \u0003\"הריני נזיר כל ימי חיי\",\u0004 או \u0003\"הריני נזיר עולם\" —\u0004 \u0003הרי זה נזיר עולם\u0004 כאבשלום. ואולם האומר: הריני נזיר לתקופה קצובה, \u0003אפילו מאה שנה,\u0004 או \u0003אפילו אלף שנים —\u0004 \u0003אין זה נזיר עולם,\u0004 עם ההלכות המיוחדות לו. \u0003אלא\u0004 בפועל הריהו \u0003נזיר לעולם,\u0004 שהרי קבע זמן ארוך ביותר לנזירותו, ואין חייו ארוכים דיים כדי להשלימה. ומכל מקום משמע שיש הבדל בין נזירות שיש לה קצבה לזו שאין לה הגדרה קצובה.","\u0003רבה אמר: שאני\u0004 \u0005[שונות\u0006\u0005]\u0006 הן \u0003שערות\u0004 מפרסות ומתחנות המנוחה שבדרך \u0003הואיל ומובדלות זו מזו,\u0004 ולכן האומר \"כשער ראשי\" הרי יש בכך התייחסות למספר של פרטים נבדלים, ומכאן — נזירויות נפרדות.","ומקשים: \u0003גבי יומי נמי הא כתיב\u0004 \u0005[אצל ימים גם כן הרי נאמר\u0006\u0005]\u0006 \u0003\"ויהי ערב ויהי בקר יום אחד\"\u0004 (בראשית א, ה), כלומר, יום נבדל לעצמו, ומדוע לא נאמר שכאשר הוא נוזר \"מכאן ועד מקום פלוני\" — הרי הוא מקבל על עצמו נזירויות כמנין הימים!","ומשיבים: \u0003התם לאו\u0004 \u0005[שם אין\u0006\u0005]\u0006 הכוונה \u0003דמפסקי מהדדי\u0004 \u0005[שנפרדים\u0006 הימים זה מזה\u0005]\u0006 \u0003הוא,\u0004 שהרי כולם רצף אחד הם. אלא \u0003מאי קאמר\u0004 \u0005[מה אומר\u0006\u0005]\u0006 הכתוב — \u0003יממא וליליא חד יומא\u0004 \u0005[יום ולילה יום אחד\u0006\u0005]\u0006 \u0003הוא, ולעולם\u0004 הם \u0003לא מפסקי מהדדי\u0004 \u0005[נפרדים זה מזה\u0006\u0005].\u0006","ועל השאלה ששאלנו בתחילה על משנתנו: והרי \"מכאן ועד סוף העולם\" הוא אומר, ונתקשינו בדבר, \u0003רבא אמר: למה לך אקשויי כולי האי\u0004 \u0005[להקשות\u0006 את כל זה\u0005],\u0006 שהקושיה אינה קיימת מעיקרה, \u0003שאני התם\u0004 \u0005[שונה שם\u0006\u0005]\u0006 במשנתנו \u0003דהא קתני\u0004 \u0005[שהרי שנה\u0006\u0005]\u0006 \u0003\"הריני נזיר אחת\"\u0004 וכיון שאמר \"אחת\", אין אנו מונים אלא לפי מה שאמר — בגודלה של נזירות אחת, ולא יותר מזו.","האומר: \u0003\"הריני נזיר ויום אחד\",\u0004 או שאמר: \u0003\"הריני נזיר ושעה אחת\",\u0004 או \u0003\"הריני נזיר אחת ומחצה\" —\u0004 \u0003הרי זה\u0004 נעשה \u0003נזיר שתים,\u0004 כלומר, שתי נזירויות זו אחר זו. שכיון שאמר \"הריני נזיר\" — חלה עליו נזירות אחת שלימה, בת שלושים יום, ואם הוסיף בקבלת נזירותו זמן נוסף (\"יום אחד\", \"שעה אחת\", \"מחצה\") — התכוון לנזירות נוספת, וכיון שאין נזירות בפחות משלושים יום, ממילא הוא נזיר שנית.","שואלים: \u0003למה לי למיתנא\u0004 \u0005[לשנות\u0006\u0005]\u0006 את \u0003כל הני\u0004 \u0005[אלה\u0006\u0005]?\u0006 הלא היה יכול להביא רק דוגמה אחת ונלמד ממנה את השאר! ומסבירים: \u0003צריכי\u0004 \u0005[צריכים\u0006\u0005]\u0006 כל הדברים להיאמר, משום \u0003דאי תנא\u0004 \u0005[שאילו\u0006 היה שונה\u0005]\u0006 רק \u0003\"הריני נזיר ויום אחד\",\u0004 אפשר היה לומר: \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 \u0003הוא דאמרינן\u0004 \u0005[שאנו אומרים\u0006\u0005]\u0006 שנוהג שתי נזירויות. שכיון שהוסיף יום אחד לנזירות, הרי \u0003אין נזירות ליום אחד, אמטו להכי קמני תרתין\u0004 \u0005[משום כך\u0006 הוא מונה שתים\u0005],\u0006 משום שאינו יכול להיות נזיר ליום אחד בלבד. \u0003אבל\u0004 האומר \u0003\"הריני נזיר ושעה אחת\" לימני\u0004 \u0005[שימנה\u0006\u0005]\u0006 \u0003שלשים ואחד יום\u0004 שהרי שעה אינה נחשבת כחלק ממנין החודש, ונאמר שהאריך זמן נזירותו ביום אחד של נזירות, וכאילו אמר \"הריני נזיר שלושים ואחד ימים\", על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שכיון שקיבל על עצמו זמן כלשהו לאחר קבלת נזירות אחת — הרי זו כקבלת נזירות נוספת, ואין נזירות פחות משלושים יום."],["\u0003ואי תנא\u0004 \u0005[ואם\u0006 היה שונה\u0005]\u0006 רק \u0003\"\u0004הריני נזיר ו\u0003שעה אחת\",\u0004 היינו אומרים שקיבל עליו שתי נזירויות \u0003משום\u0004 ש\u0003לא נחית לדוקא\u0004 \u0005[יורד\u0006 נכנס לדיוק הלשון\u0005],\u0006 ולא היתה כוונתו אלא לומר שהוא מקבל על עצמו נזירות אחת ועוד משהו מנזירות שניה, ולכן חלה עליו חובת נזירות שלימה נוספת. \u0003אבל\u0004 האומר שהוא נוזר \u0003אחת ומחצה, דנחית לדוקא\u0004 \u0005[שיורד לדיוק\u0006\u0005],\u0006 שרואים שנדר רק לזמן מסויים \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 ש\u0003לא לימני תרתי\u0004 \u0005[ימנה שתים\u0006\u0005]\u0006 אלא ימנה רק ארבעים וחמישה יום, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 את \u0003כולהו\u0004 \u0005[כולן\u0006\u0005],\u0006 שבכולן — \u0003נזיר שתים.\u0004","האומר: \u0003\"הריני נזיר שלשים יום ושעה אחת\"\u0004 — הרי הוא \u0003נזיר שלשים ואחד יום, שאין נזירות\u0004 חלה \u0003לשעות,\u0004 אלא רק ימים שלמים.","\u0003אמר רב: לא שנו\u0004 שהריהו נזיר שלושים ואחד ימים \u0003אלא\u0004 כש\u0003אמר \"שלשים ואחד יום\"\u0004 וכיוצא בזה, \u0003אבל\u0004 אם \u0003אמר \"שלשים יום ויום אחד\"\u0004 — הרי הוא \u0003נזיר שתים,\u0004 ששלושים יום הם נזירות אחת, והיום האחד הנוסף הוא התחלה של נזירות נוספת.","ומעירים ש\u0003רב סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 בענין זה \u0003כ\u0004שיטת \u0003ר' עקיבא דדריש לישנא יתירא\u0004 \u0005[שדורש לשון יתירה\u0006\u0005].\u0006 שאם משתמש אדם בדבריו בביטוי מיותר למדים מכאן שהיתה כוונתו להוסיף דברים. וכיון שאמר \"שלשים יום, ויום\" ולא כללם יחד — משמע שהתכוון לנזירות נוספת.","\u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]\u0006 בשיטת ר' עקיבא, שאדם המוכר לחבירו בית סתם — אינו מוכר בכלל זה \u0003לא את הבור, ולא את הדות\u0004 (בור בנוי מעל גבי הקרקע) \u0003אף על פי שכתב לו\u0004 בשטר שהוא מוכר לו את הבית \u0003עומקא ורומא\u0004 \u0005[בעומקו וברומו\u0006\u0005],\u0006 כי את אלה שאינם חלק מן הבית אינו כולל במכירה עד שיפרש. \u0003ו\u0004לכן \u0003צריך\u0004 המוכר \u0003ליקח\u0004 (לקנות) \u0003לו דרך\u0004 אל הבור והדות ששייר לעצמו. כי במכירת הבית מכר את כל זכויותיו, ואינו רשאי לעבור בו עוד לצורך עצמו, ואם רצונו להשתמש בבור — צריך לקנות זכות זו בחזרה מן הקונה. אלו \u0003דברי ר' עקיבא.\u0004","\u0003וחכמים אומרים: אינו צריך ליקח לו דרך\u0004 לפי שאין אומרים שהמוכר שייר לעצמו את הבור והדות בלא ששייר לעצמו גם אפשרות גישה אליהם. \u0003ומודה ר' עקיבא בזמן שאמר לו\u0004 בתוך החוזה שהוא מוכר לו את הבית \u0003\"חוץ מאלו\",\u0004 הבור והדות — \u0003שאינו צריך ליקח לו דרך.\u0004 וטעמו של ר' עקיבא, שכיון שהוסיף המוכר והדגיש שלא לצורך שהבור והדות אינם נכללים במכר, יש להבין ששייר לעצמו גם את הזכות להגיע אליהם. הרי שסבור ר' עקיבא שאם אדם משתמש בלשון יתירה שאינה נחוצה לעניינה — יש בכך כוונה מיוחדת, ויש ללמוד מלשון זו תוספת דברים. ובדרך זו הולך גם רב לענין משנתנו."],["האומר: \u0003\"הריני נזיר כשער ראשי\",\u0004 או שאמר: \u0003\"כעפר הארץ\",\u0004 או \u0003\"כחול הים\" —\u0004 \u0003הרי זה נזיר עולם,\u0004 לפי שקיבל עליו נזירויות רבות כמנין כל אלה, ובפועל הריהו נזיר לעולם, שכן הרי הם מרובים משנות חייו. \u0003ומגלח\u0004 את שערו \u0003אחת לשלשים יום.\u0004","\u0003רבי אומר: אין\u0004 נזיר \u0003זה מגלח אחת לשלשים יום,\u0004 שלדעתו קיבל אדם זה על עצמו נזירות אחת ארוכה שיימשכו ימיה כמנין שערות ראשו. \u0003ואיזהו\u0004 הנזיר שהוא \u0003מגלח אחת לשלשים\u0004 יום, אם השתמש בקבלת נזירותו בלשונות שכאלה — \u0003האומר: \"הרי עלי נזירות\u0004 (ולא \"הריני נזיר\") \u0003כשער ראשי\",\u0004 או שאומר: \u0003\"כעפר הארץ\",\u0004 או \u0003\"כחול הים\",\u0004 שבמה שנקט בלשון \"הרי עלי נזירות\" וכו' הראה שנתכוון לנזירויות שונות נבדלות זו מזו.","האומר \u0003\"הריני נזיר מלא הבית\",\u0004 או \u0003\"מלא הקופה\"\u0004 — \u0003בודקין אותו\u0004 מה היתה כוונתו, \u0003אם אמר:\u0004 נזירות \u0003אחת גדולה נזרתי,\u0004 כלומר, היתה כוונתי לנזור — הרי הוא \u0003נזיר\u0004 רק \u0003שלשים יום,\u0004 שהרי אמרה כבר המשנה (לעיל נזיר ז, א) שלענין נזירות אין מחלקים בין לשון \"קטנה\" ו\"גדולה\". \u0003ואם אמר: סתם נזרתי\u0004 ולא פירש את דבריו — \u0003רואין את הקופה כאילו היא מלאה חרדל\u0004 שהוא גרגיר קטן מאד, \u0003ו\u0004הריהו \u0003נזיר כל ימיו,\u0004 שאנו מניחים שרצה לנדור נזירויות כמנין היחידות הנכנסות לקופה זו, ואומדים זאת לפי הגרגרים הקטנים ביותר.","האומר \u0003\"הריני נזיר מכאן עד מקום פלוני\" —\u0004 \u0003אומדין כמה ימים\u0004 של הליכה יש \u0003מכאן עד\u0004 אותו \u0003מקום פלוני, אם פחות משלשים יום\u0004 — הרי הוא \u0003נזיר שלשים יום,\u0004 שאין נזירות בפחות משיעור זה. \u0003ואם לאו\u0004 \u0005[לא\u0006\u0005],\u0006 שיש מהלך יותר משלושים יום — הרי הוא \u0003נזיר כמנין הימים.\u0004","האומר: \u0003\"הריני נזיר כמנין ימות החמה\",\u0004 כלומר, כמנין ימות השנה — \u0003מונה נזירות\u0004 (מספר נזירויות) \u0003כמנין ימות החמה\u0004 בשנה, שהם שלוש מאות ששים וחמישה. \u0003אמר ר' יהודה: מעשה היה\u0004 באדם אחד שנדר נדר זה, ונהג נזירויותיו כמנין זה, ו\u0003כיון שהשלים\u0004 את כל מנין נזירויותיו — \u0003מת.\u0004","שנינו במשנה שאם אמר \"הריני נזיר מלוא הקופה\" ולא פירש את כוונתו אלא אמר \"סתם נזרתי\" — \u0003רואין את הקופה כאילו\u0004 היא \u0003מלאה חרדל ו\u0004לכן נעשה \u0003נזיר כל ימיו.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 אומדים כאילו היתה מלאה דווקא חרדל, שהוא קטן מאד? \u0003וליחזייה\u0004 \u0005[ושנראה אותה\u0006\u0005]\u0006 \u0003כאילו\u0004 היא \u0003מלאה קישואין ודלועין\u0004 שהם פירות גדולים, ומספרם בקופה קטן יותר, \u0003ותיהוי\u0004 \u0003ליה תקנתא\u0004 \u0005[ושתהיה לו תקנה\u0006\u0005]\u0006 שיסיים את חובת נזירותו בזמן קצר יותר!","\u0003אמר חזקיה:\u0004 שאלה זו אכן קיימת, ו\u0003במחלוקת\u0004 תנאים היא \u0003שנויה. ו\u0004משנתנו שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: אדם מכניס את עצמו לדבר שספיקו חמור מודאי.\u0004 שפעמים אדם אומר דבר שחוסר הבהירות או הספק שבו מכניס אותו לחומרה יתירה, ומכל מקום מקבל על עצמו דבר זה בזמן שהוא נודר. כיצד?","— \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 האומר \u0003\"הריני נזיר על מנת שיהא\u0004 (שיש) \u0003בכרי\u0004 (ערימת תבואה) \u0003זה מאה כור\u0004 (מידת נפח) \u0003\"\u0004\u0003והלך\u0004 למדוד את הכור \u0003ומצאו שנגנב או שאבד,\u0004 ואי אפשר עתה לדעת כמה היה בכרי בשעה שנדר — \u0003ר' שמעון אוסר\u0004 עליו לשתות יין ולגלח, שמא היה בכרי מאה כור, \u0003ש\u0004לדעתו \u0003ספק נזירות\u0004 דינו \u0003להחמיר.\u0004","ו\u0003ר' יהודה מתיר, ש\u0004לדעתו \u0003ספק נזירות להקל,\u0004 ואנו אומרים שמא לא היה בכרי מאה כור ולא חלה נזירותו.","\u0003ר' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר\u0006\u0005]\u0006 שמשנתנו כשיטת \u0003ר' יהודה\u0004 היא, מכל מקום יש לחלק בדברים, כי \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 ב\"על מנת שיהא בכרי זה מאה כור\" \u0003לא נחית ליה\u0004 \u0005[יורד לו\u0006\u0005]\u0006 אותו אדם \u0003לנזירות\u0004 בוודאי, אלא על תנאי, שהרי אין הוא יודע באותה עת כמה כור יש בכרי, ולא ברור כלל שחלה עליו נזירות. וכיון שלא ברור לנו שנתקיים התנאי — אנו משאירים אותו בחזקתו, ומספק לא נכניסנו בגדר נזיר. ואילו \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 במשנתנו, במלוא הקופה הרי \u0003נחית ליה\u0004 \u0005[ירד לו\u0006\u0005]\u0006 \u0003לנזירות,\u0004 שהרי ודאי קיבל על עצמו נזירות כלשהי והיא חלה עליו, אם כן \u0003במאי לסלוקיה מיניה\u0004 \u0005[במה נסלק אותה ממנו\u0006\u0005],\u0006 שהרי לא ברור מה שיעורה של נזירות זו? ובמקרה זה אף ר' יהודה מודה שמחמירים בשיעור הגדול של נזירות.","ושואלים: \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 \u0003לא\u0004 נסלק ממנו את הנזירות? \u0003ליחזיה לקופה\u0004 \u0005[נראה את הקופה\u0006\u0005]\u0006 \u0003כאילו\u0004 היא \u0003מלאה קישואין ודלועין, ותיהוי ליה תקנתא\u0004 \u0005[ותהיה לו תקנה\u0006\u0005]\u0006 וכשיסתיימו ימי נזירות אלו נאמר שנסתלק ממנו הנדר הוודאי, ומעתה צריך הוכחה להוסיף עליו נזירות. \u0003הא סלקא דעתין\u0004 \u0005[הרי עלה על דעתנו\u0006\u0005],\u0006 כך אנו סבורים ש\u0003נזירות\u0004 (כמה נזירויות) \u0003הוא דקביל עילויה\u0004 \u0005[שקיבל עליו\u0006\u0005]\u0006 ולאחר שיקיים נדרי נזירות כמנין הקישואים — יצא מכלל חיוב זה!"],["\u0003ר' יהודה סבר לה\u0004 \u0005[סבור\u0006\u0005]\u0006 הוא \u0003כ\u0004שיטת \u0003רבי. דתנן\u0004 \u0005[ש\u0006כן שנינו במשנתנו\u0005],\u0006 \u0003רבי אומר:\u0004 הנודר \"הריני נזיר כשער ראשי\" — \u0003אין זה מגלח אחת לשלשים יום\u0004 אלא אנו רואים זאת כקבלת נזירות ארוכה אחת, \u0003ואיזהו שמגלח אחת לשלשים יום —\u0004 \u0003האומר \"הרי עלי נזירות כשער ראשי\" ו\"כעפר הארץ\" ו\"כחול הים\",\u0004 שפירש שמקבל עליו נזירויות רבות. ומאחר שר' יהודה סבור כרבי נמצא שאף באומר \"הריני נזיר מלוא קופה\" סובר ר' יהודה שאין לו תקנה, כיון שקיבל עליו נזירות אחת ארוכה. ושואלים: \u0003ור' יהודה מי סבר לה\u0004 \u0005[האם סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003רבי? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הריני נזיר כמנין ימות החמה וכו'\u0004 מונה נזירויות כמנין ימות החמה. ועל כך \u0003אמר ר' יהודה: מעשה היה, וכיון שהשלים\u0004 — \u0003מת.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר\u0006\u0005]\u0006 ש\u0003נזירות\u0004 (נזירויות) רבות \u0003קא\u0004 \u0005[הוא\u0006\u0005]\u0006 \u0003מקבל עליה\u0004 \u0005[עליו\u0006\u0005]\u0006 \u0003היינו טעמא\u0004 \u0005[זהו הטעם\u0006\u0005]\u0006 ההסבר למה שאמר, ש\u0003כיון\u0004 ש\u0003השלים\u0004 שלוש מאות שישים וחמש נזירויות של חודש — \u0003מת. אלא אי אמרת\u0004 \u0005[אם אומר אתה\u0006\u0005]\u0006 שלדעת ר' יהודה \u0003חדא נזירות\u0004 \u0005[נזירות אחת\u0006\u0005]\u0006 \u0003קבל עילויה\u0004 \u0005[עליו\u0006\u0005]\u0006 ואינו סבור כדעת סתם משנה — \u0003מי הוי\u0004 \u0005[האם היא\u0006\u0005]\u0006 \u0003השלמה כלל?\u0004 כלומר, לא היה משתמש בלשון \"שהשלים\" לדבר שאינו כדעתו כלל.","","","\u0003ועוד: מי סבר לה\u0004 \u0005[האם\u0006 ר' יהודה סבור הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003רבי? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 האומר \u0003\"הריני נזיר מנין הילקטי קיץ\"\u0004 (כמנין תילי התאנים המונחות לייבוש), או \u0003מנין שבלי שמיטה\u0004 — הרי הוא \u0003מונה נזירות\u0004 רבות \u0003כמנין הילקטי קיץ וכמנין שבלי שמיטה,\u0004 הרי שר' יהודה אינו סבור שמקבל על עצמו נזירות אחת ארוכה!","ודוחים: מכאן אין ראיה שר' יהודה אינו סובר כרבי, שכן \u0003\"מנין\" שאני\u0004 \u0005[שונה\u0006\u0005].\u0006 כי כאשר פירש ואמר \"מנין\", מובן מדבריו שקיבל על עצמו מספר רב של נזירויות, ואף רבי סובר שאם אמר במפורש \"מנין\", לא ינהוג נזירות אחת ארוכה.","ושואלים: \u0003ומי שאני ליה\u0004 \u0005[והאם שונה לו\u0006\u0005]\u0006 \u0003לרבי\u0004 הדין כשאומר בעת נזירותו במפורש \u0003מנין\u0004 שהדבר נחשב לו כנודר נזירויות חלוקות? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 האומר \u0003\"הריני נזיר\u0004 \u0003כמנין ימות החמה\" —\u0004 \u0003מונה נזירות כמנין ימות החמה.\u0004 האומר \u0003\"כימי הלבנה\" —\u0004 \u0003מונה\u0004 מספר נזירויות \u0003כ\u0004מנין \u0003ימי הלבנה. רבי אומר: עד שיאמר \"נזירות עלי כמנין ימות החמה וכמנין ימות הלבנה\"\u0004 ואם לא אמר כן — מפרשים שכוונתו היתה לנזירות אחת ארוכה אף שנקט לשון \"מנין\"! ומשיבים: \u0003ר' יהודה סבר לה כותיה בחדא ופליג עליה בחדא\u0004 \u0005[סבור\u0006 הוא כמותו באחת וחולק עליו באחת\u0005].\u0006 ומפרטים: \u0003סבר לה כותיה בחדא\u0004 \u0005[סבור\u0006 הוא כמותו באחת\u0005]\u0006 — ש\u0003נזירות\u0004 ארוכה \u0003קביל עילויה\u0004 \u0005[קיבל עליו\u0006\u0005]\u0006 אם אמר \"הריני נזיר כשער ראשי\", שיהיו ימיה כשיער ראשו, ומשום כך אינו יכול להסתלק ממנה. \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחת\u0006\u0005]\u0006 — ש\u0003אילו ר' יהודה שני ליה\u0004 \u0005[שונה לו\u0006\u0005]\u0006 \u0003מונה,\u0004 שאם פירש \"מנין\" רואים זאת כקבלת מנין נזירויות מסויים, \u0003ורבי לא שני ליה\u0004 \u0005[שונה לו\u0006\u0005]\u0006 \u0003מונה,\u0004 עד שיפרש שהוא מקבל נזירויות נבדלות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 האומר \u0003\"הריני נזיר כל ימי חיי\",\u0004 או \u0003\"הריני נזיר עולם\" —\u0004 \u0003הרי זה נזיר עולם,\u0004 ונוהג כאבשלום שמיקל שערו בתער ומגלח בסוף כל שנה. המקבל עליו נזירות לפרק זמן קצוב, \u0003אפילו \"מאה שנה\" אפילו \"אלף שנים\" —\u0004 \u0003אין זה נזיר עולם, אלא\u0004 בפועל הריהו \u0003נזיר\u0004 נזירות אחת הנמשכת \u0003לעולם.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 האומר \u0003\"הריני נזיר ואחת\"\u0004 — הרי זה \u0003מונה שתים\u0004 (שתי נזירויות), שנדר תחילה להיות נזיר, וחזר ואמר שמקבל עוד נזירות אחת. האומר: \u0003\"\u0004הריני נזיר ואחת \u0003ועוד\" —\u0004 \u0003מונה שלש\u0004 נזירויות. ואם מוסיף על כך \u0003\"ושוב\" —\u0004 \u0003מונה ארבע.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006\u0005]\u0006 שכן הוא בהלכה אחרונה זו (\"ושוב\"), ולשם מה לומר לנו את הדבר? ומשיבים: יש חידוש בכך, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]\u0006 \u0003\"ושוב\"\u0004 כוונתו \u0003כי כולהו\u0004 \u0005[כמו כל אלה\u0006\u0005]\u0006 שמנה קודם, \u0003והויא ליה שית\u0004 \u0005[והרי הן שש\u0006\u0005]\u0006 נזירויות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 ש\u0003לא.\u0004 ובענין דומה בלשונות של קבלת נזירות \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 האומר \u0003\"הריני נזיר\"\u0004 והוסיף מספר בשפה אחרת, \u0003סומכוס אומר:\u0004 אמר \u0003\"\u0004הריני נזיר \u0003הן\"\u0004 שהוא ביוונית אחת — קיבל עליו נזירות \u0003אחת,\u0004 האומר \u0003\"דיגון\"\u0004 (שתי צלעות) — קיבל עליו \u0003שתים, \"טריגון\"\u0004 (משולש) — קיבל עליו \u0003שלש, \"טטרגון\"\u0004 (מרובע) — קיבל עליו \u0003ארבע, \"פונטיגון\"\u0004 (מחומש) — קיבל עליו \u0003חמש.\u0004 כיון שהזכרנו את המילים הללו, מביאים ברייתא אחרת המזכירה אותן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003בית עגול,\u0004 בית \u0003דיגון\u0004 (בעל שתי צלעות) ובית \u0003טריגון\u0004 (משולש) \u0003ופונטיגון\u0004 (בעל חמש צלעות) — \u0003אינו מטמא בנגעים, טטרגון\u0004 (מרובע) — \u0003מטמא בנגעים. מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר? \u0003למטה הוא אומר\u0004 לא \u0003\"קיר\"\u0004 אלא \u0003\"קירת\"\u0004 (\"והנה פשה הנגע בקירות הבית\". ויקרא יד, לט) וכיון שהשתמש כאן בלשון רבים, אף שאין צורך בכך — הרי שנים, ו\u0003למעלה\u0004 (מקודם) \u0003הוא אומר \"קיר\" \"קירת\"\u0004 (\"והנה הנגע בקירות הבית\". ויקרא יד, לז) — \u0003הרי כאן ארבע\u0004","","","","","",""],["האומר \u0003\"הריני נזיר מן הגרוגרות\u0004 (תאנים מיובשות) \u0003ומן הדבילה\u0004 (גוש של תאנים מיובשות) \u0003\"\u0004— \u0003בית שמאי אומרים:\u0004 במה שאמר \"הריני נזיר\" — הריהו \u0003נזיר\u0004 גמור, ומה שהוסיף ואמר \"מן הגרוגרות\" שאינן בכלל איסורי נזיר, שהרי הן מן התאנים ולא מן הגפן — אין בדבריו ממש. \u0003ובית הלל אומרים: אינו נזיר,\u0004 שלא קיבל עליו נזירות. \u0003אמר ר' יהודה: אף כשאמרו בית שמאי\u0004 שנדר זה חל עליו, \u0003לא אמרו אלא באומר\u0004 שכוונתו \u0003\"הרי הן עלי קרבן\"\u0004 שרצה לומר שהוא מתנזר מהן, והרי זה כמי שרצה לומר שהוא נודר מהן. אבל אף בית שמאי אינם סבורים שיש כאן נדר נזירות, אלא נדר סתם.","שנינו במשנה: האומר \u0003\"הריני נזיר מן הגרוגרות ומן הדבילה\"\u0004 — \u0003בית שמאי אומרים:\u0004 הריהו \u0003נזיר.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע\u0006\u0005]?\u0006 הלא בפרשת נזירות \u0003\"מכל אשר יעשה מגפן היין...\u0004 לא יאכל\u0003\"\u0004 (במדבר ו, ד), \u0003אמר רחמנא\u0004 \u0005[אמרה תורה\u0006\u0005],\u0006 ואם כן, אין נזירות אלא מיין ולא מדבר אחר! ומשיבים: \u0003בית שמאי סברי לה\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר: אין אדם מוציא דבריו לבטלה,\u0004 ואם מוציא אדם מפיו דבר שאי אפשר לקיימו בדיוק כפי שאמרו, אנו אומרים שנתכוון בעצם לומר דבר של ממש. ואף כאן אומרים אנו שאכן טעה האומר בדבריו, אבל באמת נתכוון לנזירות ממש.","\u0003ו\u0004אילו \u0003בית הלל סברי לה\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר:\u0004 אף \u0003בגמר דבריו אדם נתפס.\u0004 שאם אמר אדם שני דברים בזה אחר זה ואינם מתיישבים זה עם זה, כגון שאמר שתהא בהמתו \"תמורת עולה תמורת שלמים\", הולכים גם אחר משמעות לשונו האחרונה, ואין מבטלים אותם, וחלים על הבהמה שני הנדרים. \u0003ו\u0004אם כן, \u0003האי\u0004 \u0005[זה\u0006\u0005]\u0006 \u0003נדר ופתחו עמו הוא,\u0004 שיש כאן קבלת נדר והתרת הנדר כאחת, שאמנם אמר \"הריני נזיר\", אבל במה שהוסיף ואמר \"מן הגרוגרות ומן הדבילה\" נמצא שביטל את נדר נזירותו באותו משפט עצמו.","ומקשים על הסבר זה של המחלוקת: \u0003ובית שמאי נמי\u0004 \u0005[גם כן\u0006\u0005],\u0006 הלא \u0003נדר ופתחו עמו הוא\u0004 ובוודאי אינם חולקים שאין נדר כזה חל כלל!","\u0003אלא\u0004 יש לומר כך: \u0003בית שמאי\u0004 אכן \u0003סברי לה\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 ש\u0003אמר: אין אדם מוציא דבריו לבטלה. וכיון\u0004 ש\u0003אמר \"הריני נזיר\"\u0004 אם כן מיד באמירה זו \u0003הוה ליה\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר, כי קאמר\u0004 \u0005[כאשר\u0006 הוא מוסיף ואומר\u0005]\u0006 \u0003\"מן הגרוגרות ומן הדבילה\" —\u0004 \u0003לאיתשולי\u0004 \u0005[להישאל\u0006\u0005]\u0006 על נדרו \u0003הוא דקאתי\u0004 \u0005[שבא\u0006\u0005],\u0006 כלומר, הוא רוצה עכשיו להתחרט על הנדר שעשה קודם, ולכן מוסיף דברים כדי לבטלו. \u0003ובית שמאי לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005]\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם אומרים\u0005]:\u0006 \u0003אין שאלה בהקדש,\u0004 שאם הקדיש אדם דבר אינו יכול לבוא לחכם ולהישאל על הקדש זה ולבטלו, כפי שיכול לעשות בנדרים רגילים כאשר אדם אוסר על עצמו דבר. \u0003וכיון\u0004 ש\u0003אין שאלה בהקדש —\u0004 \u0003אין שאלה\u0004 גם \u0003בנזירות\u0004 שדינה כהקדש לענין זה.","\u0003ו\u0004אילו \u0003בית הלל סברי\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון, דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005],\u0006 כאשר נדר אדם מנחה מן השעורים (ואין מנחת נדבה אלא מן החיטים), יש חכמים הסבורים שיביא מנחת חיטים, \u0003ו\u0004אילו \u0003ר' שמעון פוטר\u0004 אותו לגמרי, כיון \u0003שלא התנדב כדרך המתנדבים.\u0004 שכיון שנדב דבר שאין מתנדבים כמותו — אין ממש בדבריו ובטלו לגמרי. ואף כאן, כיון שקיבל עליו נזירות בגרוגרות ולא ביין — בטלו דבריו לגמרי."],["מעירים: \u0003לא כי האי תנא\u0004 \u0005[כמו,\u0006 כשיטת תנא זה היא\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' נתן אומר:\u0004 האומר \"הריני נזיר מן הגרוגרות\", \u0003בית שמאי אומרים:\u0004 הריהו גם \u0003נדור,\u0004 אסור בנדר מן הגרוגרות, \u0003ו\u0004גם \u0003נזיר\u0004 כשאר נזירים. \u0003ובית הלל אומרים: נדור,\u0004 שהנדר מן הגרוגרות חל עליו \u0003ואין\u0004 הוא נעשה בכך \u0003נזיר.\u0004 ולפי שיטה זו \u0003בית שמאי סברי לה\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 שאין אדם מוציא דבריו לבטלה, ולכן כיון שאמר \"הריני נזיר\" — חלה עליו נזירות ממש, ולכל דבריו היתה משמעות, \u0003וכ\u0004דעת \u0003ר' יהודה\u0004 הסבור שכיון שהזכיר איסור גרוגרות חל עליו נדר, ואסור בהן. \u0003ובית הלל סברי לה\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 שבגמר דבריו אדם נתפס, ואם מביאים בחשבון את גמר דבריו הרי היה כאן נדר מן הגרוגרות.","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[\u0006בלשון אחרת, נוסח אחר, אומרים אותה ברייתא\u0005]\u0006 כך: \u0003ר' נתן אומר, בית שמאי אומרים:\u0004 הריהו \u0003נדור\u0004 בכך \u0003ואינו נזיר, ובית הלל אומרים:\u0004 הריהו \u0003לא נדור ולא נזיר.\u0004 ולפי שיטה זו \u0003בית שמאי כ\u0004שיטת \u0003ר' יהודה\u0004 במשנתנו, \u0003ובית הלל כ\u0004שיטת \u0003ר' שמעון,\u0004 שהנודר דבר שלא כדרך המתנדבים — אינו נדר כלל.","ודנים עתה בדברים שמקצתם הוזכרו מקודם (דעת ר' שמעון). \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003האומר \"הרי עלי מנחה להביא מן השעורים\"\u0004 בעוד שאין מביאים מנחת נדבה אלא מן החיטים — \u0003יביא\u0004 מנחה \u0003מן החיטים.\u0004 האומר \u0003\"\u0004הרי עלי מנחה מן ה\u0003קמח\"\u0004 וסתם מנחה היא סולת — \u0003יביא סולת.\u0004 אמר \u0003\"\u0004הרי עלי מנחה \u0003שלא בשמן ולבונה\" —\u0004 \u0003יביאנה בשמן ולבונה,\u0004 כדינה. האומר \u0003\"\u0004הרי עלי מנחה \u0003חצי עשרון\"\u0004 של סולת — \u0003יביא עשרון שלם\u0004 (עשירית האיפה), שאין מנחה פחותה מעשרון. האומר \u0003\"עשרון ומחצה\" —\u0004 \u0003יביא שנים,\u0004 שיש פה נדר של עשרון כדינו, ועוד נדר של חצי עשרון, שאמרנו שצריך להביא עשרון שלם. \u0003ר' שמעון פוטר\u0004 בכל אלה, כיון \u0003שלא התנדב כדרך המתנדבים\u0004 והנדר לא חל כלל.","ושואלים: \u0003מאן\u0004 \u0005[מיהו\u0006\u0005]\u0006 ה\u0003תנא\u0004 הסבור \u0003דכי אמר\u0004 \u0005[שכאשר\u0006 הנודר אומר\u0005]\u0006 \u0003\"הרי עלי מנחה מן השעורים\" מביא\u0004 מנחה \u0003מן החיטים? אמר חזקיה:\u0004 הלכה זו \u0003במחלוקת\u0004 תנאים היא \u0003שנויה, ו\u0004בשיטת \u0003בית שמאי היא.\u0004 ומסביר: \u0003לאו אמרי\u0004 \u0005[האם לא אמרו\u0006\u0005]\u0006 \u0003בית שמאי כי אמר\u0004 \u0005[\u0006שכאשר הוא אומר\u0005]\u0006 \u0003\"\u0004הריני נזיר \u0003מן הגרוגרות ומן הדבילה\" הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר,\u0004 משמע שאנו תופסים את תחילת דבריו, ואין אנו מתחשבים בתנאי המיוחד שהתנה, \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 \u0003כי אמר\u0004 \u0005[כאשר\u0006 הוא אומר\u0005]\u0006 \u0003\"\u0004הרי עלי מנחה \u0003מן השעורין\" —\u0004 \u0003מביא מן החיטים,\u0004 וכן בשאר הדברים המוזכרים במשנה זו.","\u0003ור' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר\u0006\u0005]\u0006 שדעת חכמים החולקים על ר' שמעון במשנה זו כ\u0003דברי הכל,\u0004 ואף כדברי בית הלל — יש לפרש שמדובר שם \u0003באומר\u0004 אחרי כן ומפרש את דבריו \u0003\"אילו הייתי יודע שאין נודרין כך,\u0004 כלומר, שאי אפשר להתנדב מנחה מן השעורים, \u0003לא נדרתי כך אלא כך\",\u0004 כלומר, מן החיטים. שבעצם לא היה כאן תנאי אלא טעות היתה בידו, ובעצם התכוון להביא מנחה כדין. ובמקרה זה, אף בית הלל שסבורים במשנתנו שאינו נדור כלל, חייבוהו במנחה.","ובהלכה זו הוסיף ו\u0003אמר חזקיה: לא שנו\u0004 שצריך להביא מנחה מן החיטים \u0003אלא\u0004 בזמן \u0003שאמר\u0004 \u0003\"\u0004הרי עלי מנחה \u0003מן השעורים\", אבל\u0004 אם \u0003אמר\u0004 שהוא מתנדב מנחה \u0003מן העדשים —\u0004 \u0003לא מייתי\u0004 \u0005[אינו מביא\u0006\u0005]\u0006 \u0003ולא כלום,\u0004 כי במקדש היתה גם מנחת שעורים (מנחת העומר, מנחת סוטה) ולכן אם אמר \"מן השעורים\" יש מקום לומר שהתכוון למנחת נדבה כתיקונה, אלא שטעה וחשב שאף מנחת נדבה תוכל להיות מן השעורים. אבל האומר \"מן העדשים\" הרי הכל יודעים שאין מנחה מן העדשים, ודבריו מוכיחים שאינו מתכוון כלל להביא מנחה.","ושואלים: \u0003מכדי\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003חזקיה כמאן מוקים לה למתניתין\u0004 \u0005[כ\u0006שיטת מי מעמיד, מפרש, את דעת חכמים במשנתנו במנחות\u0005] —\u0006 \u0003כ\u0004דעת \u0003בית שמאי, והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003עדשים לגבי מנחה, כגרוגרות לגבי נזיר דמו\u0004 \u0005[\u0006הן נחשבות\u0005],\u0006 שאף כאן הכל יודעים שאין נזירות מן התאנים, \u0003ו\u0004בכל זאת \u0003קאמרי\u0004 \u0005[אומרים\u0006\u0005]\u0006 \u0003בית שמאי\u0004 כי \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר!\u0004 ואם כן מדוע האומר \"הרי עלי מנחה מן העדשים\" לא יחשב כנודר מנחה? ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו\u0006\u0005]\u0006 \u0003חזקיה\u0004 מדבריו, וסבור שאין משנה זו במנחות כבית שמאי.","ושואלים: \u0003ו\u0004באמת \u0003אמאי הדר ביה\u0004 \u0005[מדוע חזר בו\u0006\u0005]?\u0006 \u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתנו\u0006 זו היתה קשה לו\u0005]\u0006 ומתוך שהתקשה בה, הבין שאין פירושו נכון. ומדוע, כי אם כשיטת בית שמאי בנזיר היא, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003דתני\u0004 \u0005[ששונה\u0006\u0005]\u0006 דין זה באומר \u0003\"\u0004הרי עלי מנחה \u0003מן השעורים\"? ליתני\u0004 \u0005[שישנה\u0006\u0005]\u0006 מקרה שיש בו חידוש גדול יותר — \u0003\"\u0004הרי עלי מנחה \u0003מן העדשים\"\u0004 שחייב בכל זאת מנחה מן החיטים! \u0003אלא סבר חזקיה: כי קאמרי\u0004 \u0005[\u0006שכאשר אמרו\u0005]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם\u0006 במשנתנו\u0005]\u0006 לגבי נזיר, היתה דעתם \u0003כ\u0004דעת \u0003ר' יהודה\u0004 שיש כאן נדר מגרוגרות — משום שעל כל פנים יש משמעות מסויימת לדבריו, שהרי נודרים בכגון זה. אבל גם הם מסכימים שלגבי דבר שאין לו משמעות כלל, כמנחה מן העדשים — לא אמר כלום.","\u0003ור' יוחנן אמר: אפילו\u0004 האומר \u0003\"\u0004הרי עלי מנחה \u0003מן העדשים\"\u0004 — הרי עליו להביא מנחה מן החיטים. ושואלים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003ר' יוחנן הוא\u0004 ש\u0003אמר\u0004 שיש להעמיד משנה זו \u0003באומר \"אילו הייתי יודע שאין נודרין כך לא נדרתי כך אלא כך\"\u0004 ובוודאי אדם יודע שאין מביאים מנחה מן העדשים, ולא היה מקום לטעות כזו! ומשיבים: \u0003לדבריו\u0004 של \u0003חזקיה הוא דקאמר\u0004 \u0005[שאמר\u0006\u0005],\u0006 שאין הוא אומר זאת כסברת עצמו, אלא על פי שיטתו של חזקיה.","וכך הוא אומר: \u0003את מאי טעמא קא הדרת\u0004 \u0005[אתה, מה טעם חוזר אתה\u0006\u0005]\u0006 \u0003בך\u0004 מפירושך הקודם, שמשנה זאת היא לשיטת בית שמאי — \u0003משום\u0004 ש\u0003לא קתני\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003\"מן העדשים\".\u0004 אולם זו אינה קושיה ניצחת, \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה הוא אומר\u0006\u0005],\u0006 כלומר, צריך להבין את הדברים בסגנון הבא: \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 לומר \u0003כי אמר\u0004 \u0005[כאשר\u0006 הוא אומר\u0005]\u0006 \u0003\"\u0004הרי עלי מנחה \u0003מעדשים\" —\u0004 \u0003דמייתי\u0004 \u0005[שמביא\u0006\u0005]\u0006 \u0003מנחה מעלייתא\u0004 \u0005[מעולה\u0006\u0005]\u0006 של חיטים, \u0003דאיכא למימר מיהדר הוא דהדר ביה\u0004 \u0005[שיש לומר\u0006 שחזר בו\u0005]\u0006 בדבריו \"מן העדשים\" מכוונתו הראשונה ורצה לבטל את נדרו, \u0003ו\u0004אף על פי כן אומרים בית שמאי: \u0003תפוס לשון ראשון\u0004 שאמר \"הרי עלי מנחה\", ומה שאחר כך הוסיף דברים, הריהו כשאלה בהקדש, שאינה חלה לדעת בית שמאי. \u0003אלא\u0004 אפילו \u0003כי אמר\u0004 \u0005[כאשר\u0006 הוא אומר\u0005]\u0006 \u0003\"\u0004הרי עלי מנחה \u0003מן השעורין\",\u0004 שיש מקום לפרש \u0003ודאי דהכי קאמר\u0004 \u0005[שכך אמר\u0006\u0005]:\u0006 \u0003אי קדשה\u0004 \u0005[אם תקדש\u0006\u0005]\u0006 המנחה הזו שהוא מתנדב מן השעורים \u0003כמנחת העומר,\u0004"],["\u0003או כמנחת סוטה\u0004 הבאות מן השעורים — \u0003תקדוש\u0004 \u0005[תתקדש\u0006\u0005],\u0006 \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003לא\u0004 יכולה להתקדש — \u0003לא\u0004 תהא זו מנחה כלל. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 בכל זאת \u0003דמייתי\u0004 \u0005[שמביא\u0006\u0005]\u0006 \u0003מן החיטים.\u0004 ואם כן אין פירכה לשיטת חזקיה מכאן, ולא היה צריך לחזור בו.","\u0003אמר\u0004 ביטוי כזה: \u0003\"אמרה פרה זו הריני נזירה אם עומדת אני\",\u0004 או אמר: \u0003\"אומר הדלת הזה הריני נזירה אם נפתח אני\"\u0004 — \u0003בית שמאי אומרים:\u0004 הרי זה \u0003נזיר, ובית הלל אומרים: אינו נזיר. אמר ר' יהודה: אף כשאמרו בית שמאי, לא אומרים\u0004 הם את דבריהם \u0003אלא באומר \"הרי פרה זו עלי קרבן,\u0004 כלומר, אסורה עלי בנדר \u0003אם עומדת היא\",\u0004 אבל נזירות אין כאן.","ושואלים: \u0003פרה מי קא מישתעיא\u0004 \u0005[האם\u0006 היא מדברת\u0005]?\u0006 כלומר, מה משמעו של הביטוי \"אמרה פרה הריני נזירה\"? \u0003אמר רמי בר חמא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים\u0006\u0005]\u0006 — \u0003כגון שהיתה פרה רבוצה לפניו\u0004 והוא מנסה להקימה ואינה קמה, \u0003ואמר: כסבורה פרה זו\u0004 שהיא \u0003אינה עומדת —\u0004 \u0003הריני נזיר מבשרה אם עמדה מאליה. ועמדה\u0004 הפרה \u0003מאליה. והלכו בית שמאי לשיטתן ובית הלל לשיטתן.\u0004","\u0003בית שמאי דאמרי\u0004 \u0005[שאומרים\u0006\u0005]\u0006 שהאומר \u0003\"\u0004הריני נזיר \u0003מן הגרוגרות ומן הדבילה\" הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר —\u0004 \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 \u0003כי אמר\u0004 \u0005[כאשר\u0006 הוא אומר\u0005]\u0006 \u0003\"\u0004הריני נזיר \u0003מבשרה\" הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר,\u0004 שאין אדם מוציא דבריו לבטלה, ותופסים אנו את ראשית דבריו שאמר \"הריני נזיר\", ומה שאמר \"מבשרה\" — אינו מעלה ואינו מוריד. \u0003ובית הלל אומרים: לא הוי\u0004 \u0005[אינו\u0006\u0005]\u0006 \u0003נזיר.\u0004","ומקשים: אם כך פירוש הדברים שבעצם אמר \"הריני נזיר מבשרה\", וכדברי רמי בר חמא, \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 כבר \u0003אמרוה בית שמאי\u0004 להלכה זו \u0003חדא זימנא\u0004 \u0005[פעם אחת\u0006\u0005],\u0006 שהרי לשיטת רמי בר חמא אין הבדל בין משנה זו ובין המשנה הקודמת אלא בניסוח! \u0003אמר רבא: תרתי תלת\u0004 \u0005[שתים שלוש\u0006\u0005]\u0006 דוגמאות מביאים חכמים במקרים שונים, שיש בכל אחת מהן חידוש, אם כי העקרון אחד הוא. \u0003וכן תני\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003ר' חייא תרתי תלת\u0004 \u0005[שתים שלוש\u0006\u0005]\u0006 דוגמאות באותו ענין. \u0003וכן אמר ר' אושעיא תרתי תלת\u0004 \u0005[שתים שלוש\u0006\u0005]\u0006 דוגמאות.","ומסבירים: \u0003וצריכי\u0004 \u0005[וצריכים\u0006\u0005]\u0006 כולם להיאמר; \u0003דאי איתמר בהא\u0004 \u0005[שאם היה נאמר\u0006 רק בזו\u0005],\u0006 דהיינו \u0003גרוגרות ודבילה,\u0004 היינו אומרים: דווקא \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003הוא דאמרי\u0004 \u0005[שאומרים\u0006\u0005]\u0006 \u0003בית שמאי\u0004 כי \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 בכך \u0003נזיר, משום דמיחלפן\u0004 \u0005[ש\u0006הם, הגרוגרות והדבילה, מתחלפים\u0005]\u0006 \u0003בענבים,\u0004 ויש לומר שלענבים התכוון. \u0003אבל בשר בענבים\u0004 ודאי \u0003לא מיחלף\u0004 \u0005[מתחלף\u0006\u0005],\u0006 ומשום כך במקרה שבמשנתנו אינו נזיר לדעת בית שמאי. \u0003ואי איתמר\u0004 \u0005[ואם היה נאמר\u0006\u0005]\u0006 דין זה רק ב\u0003בשר,\u0004 היינו אומרים: \u0003הכא הוא דאמרי\u0004 \u0005[כאן,\u0006 בבשר, הוא שאומרים\u0005]\u0006 \u0003בית שמאי\u0004 כי \u0003הוי\u0004 \u0005[הוא\u0006\u0005]\u0006 \u0003נזיר\u0004 משום שמדובר \u0003בבישרא וחמרא\u0004 \u0005[בבשר ויין\u0006\u0005]\u0006 שמדברים בהם תמיד כאחד, ויש לומר שהתכוון ליין. \u0003אבל גרוגרות ודבילה\u0004 שאין להם כל קשר עם יין — \u0003לא\u0004 תהא זו נזירות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שבשני המקרים נזיר הוא.","\u0003ואי איתמר הני תרתי\u0004 \u0005[ואילו היו נאמרים\u0006 רק אלה השנים\u0005],\u0006 גרוגרות, דבילה ובשר, היינו אומרים: \u0003הני הוא דקאמרי\u0004 \u0005[\u0006באלה הוא שאמרו\u0005]\u0006 \u0003בית שמאי, אבל דלת אימא מודו להו\u0004 \u0005[אמור\u0006 שמודים הם להם\u0005]\u0006 \u0003לבית הלל\u0004 שבכגון זה בודאי אין כאן נזירות, על כן היה צריך לומר מקרה זה גם כן. \u0003ואי תנא\u0004 \u0005[ואילו היה שונה\u0006\u0005]\u0006 \u0003דלת\u0004 בלבד, היינו אומרים להיפך: \u0003בהא קאמרי\u0004 \u0005[בזו אמרו\u0006\u0005]\u0006 \u0003בית הלל\u0004 שאין זו נזירות, \u0003אבל בהך תרתי\u0004 \u0005[באלה השניים\u0006\u0005]\u0006 הקודמים \u0003אימא מודו להו\u0004 \u0005[אמור\u0006 שמודים להם\u0005]\u0006 \u0003לבית שמאי\u0004 שיש בכך קבלת נזירות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 ש\u0003לא.\u0004 אף שרבא סילק קושי אחד שהיה על פירושו של רמי בר חמא, מכל מקום הוא מקשה עליו לגופו.","\u0003אמר רבא: מי קתני\u0004 \u0005[האם שנה\u0006\u0005]\u0006 במשנה \u0003\"אם עמדה מאליה\"?\u0004 הלוא דבר זה לא נאמר, ורמי בר חמא מוסיף חלק עיקרי שאיננו שנוי במשנה! \u0003אלא אמר רבא:\u0004 כאן מדובר \u0003כגון שהיתה פרה רבוצה לפניו\u0004 ואינה זזה כלל, \u0003ואמר \"הרי\u0004 היא \u0003עלי קרבן\",\u0004 וכך יש להבין את לשון המשנה. ומקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003פרה בת קרבן היא, אלא דלת בת קרבן היא?!\u0004 ומה מקום פה לנדר קרבן? \u0003אלא אמר רבא\u0004 כך צריך לומר: \u0003כגון שהיתה פרה רבוצה לפניו\u0004 ולא קמה,"],["\u0003ואמר \"הריני נזיר מיין אם לא עמדה\u0004 פרה זו \u0003\",\u0004 כי אני אכריח אותה לעמוד. \u0003ועמדה\u0004 הפרה \u0003מאליה\u0004 ולא הוא שהעמיד אותה. \u0003בית שמאי סברי\u0004 \u0005[סבורים\u0006\u0005]:\u0006 \u0003תורפיה דהאי גברא\u0004 \u0005[עיקרו,\u0006 עיקר נדרו \u0005של איש זה]\u0006 \u0003משום אוקמה בידיה\u0004 \u0005[העמדתה בידיו\u0006\u0005]\u0006 \u0003הוא, והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003לא אוקמה\u0004 \u0005[העמידה\u0006\u0005]\u0006 ואם כן חל עליו נדר נזירות, שהרי הוא עצמו לא הצליח להעמיד אותה. \u0003ובית הלל סברי\u0004 \u0005[סבורים\u0006\u0005]:\u0006 עיקרו של הנדר \u0003משום דרביעא\u0004 \u0005[שהיא רובצת]\u0006 \u0003הוא, והא קמת\u0004 \u0005[והרי עומדת\u0006\u0005],\u0006 וכיון שעמדה הפרה מאליה בכל דרך שהיא — אין כאן נזירות.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 רבא מפרש, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את סופה\u0005]\u0006 של המשנה, \u0003אמר ר' יהודה:\u0004 \u0003אף כשאמרו בית שמאי, לא אמרו אלא באומר \"הרי הן\u0004 (הפרה או הדלת) \u0003עלי קרבן\".\u0004 וכי \u0003פרה\u0004 זו \u0003מי קא\u0004 \u0005[האם הוא\u0006\u0005]\u0006 \u0003מתפיס בה מידי\u0004 \u0005[איזה דבר]\u0006 שיהיה בה נדר? והרי לשיטה זו לא נדר כלל מן הפרה אלא במפורש נדר נזיר, ואין הפרה נזכרת בנדר אלא בשאלה האם תעמוד או לא!","\u0003אלא\u0004 יש לומר שמדובר כאן \u0003כגון\u0004 ש\u0003אמר \"הריני נזיר מבשרה אם לא עמדה\", ועמדה\u0004 הפרה \u0003מאליה. בית שמאי סברי\u0004 \u0005[סבורים\u0006\u0005]:\u0006 \u0003תורפיה דההוא גברא\u0004 \u0005[עיקרו,\u0006 עיקר נדרו של איש זה\u0005]\u0006 \u0003משום אוקמה בידיה\u0004 \u0005[העמדתה בידיו\u0006\u0005]\u0006 \u0003הוא, והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003לא אוקמה\u0004 \u0005[העמידה\u0006\u0005].\u0006 \u0003ובית הלל סברי\u0004 \u0005[סבורים\u0006\u0005]:\u0006 \u0003תורפיה דהאי גברא\u0004 \u0005[עיקרו,\u0006 עיקר נדרו של איש זה\u0005]\u0006 \u0003משום דרביעא\u0004 \u0005[שהיא רובצת]\u0006 \u0003והא קמת\u0004 \u0005[והרי עמדה\u0006\u0005].\u0006","ושואלים: \u0003ו\u0004כי \u0003בית הלל סברי\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003אי\u0004 \u0005[\u0006שאם\u0005]\u0006 \u0003לא קמת הוי\u0004 \u0005[תעמוד\u0006 הפרה, יהיה\u0005]\u0006 \u0003נזיר? והאמרי\u0004 \u0005[והרי אומרים\u0006 הם\u0005]\u0006 שאם אומר \"הריני נזיר \u0003מבשרה\u0004 של פרה\" \u0003לא הוי\u0004 \u0005[יהיה\u0006\u0005]\u0006 \u0003נזיר,\u0004 וכפי שנחלקו בענין זה במשנה הקודמת בענין גרוגרות!","ומשיבים: יש לומר כי \u0003לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005]\u0006 של \u0003בית שמאי קאמרי\u0004 \u0005[הם אומרים\u0006\u0005]:\u0006 \u0003לדידן\u0004 \u0005[\u0006לשיטתנו שלנו\u0005]\u0006 \u0003אפילו\u0004 אם \u0003לא קמת\u0004 \u0005[תעמוד\u0006\u0005]\u0006 הפרה, \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא הוי\u0004 \u0005[יהיה\u0006\u0005]\u0006 \u0003נזיר,\u0004 שאין נדר נזירות חל באופן שאמר \"הריני נזיר\" על דבר שאינו בכלל איסורי הנזירות. ואולם \u0003לדידכו דאמריתו הוי\u0004 \u0005[לפי\u0006 שיטתכם \u0005שלכם שאתם אומרים\u0006, שהרי \u0005הוא]\u0006 \u0003נזיר,\u0004 \u0003אודו לן מיהת\u0004 \u0005[הודו לנו על כל פנים\u0006\u0005]\u0006 \u0003דתורפיה דהדין גברא\u0004 \u0005[שעיקרו,\u0006 עיקר נדרו \u0005של איש זה]\u0006 \u0003משום דרביעא, והא קמת\u0004 \u0005[ש\u0006היא רובצת, והרי עמדה\u0005]\u0006 ואם כן אין פה נזירות. \u0003ובית שמאי\u0004 סבורים: \u0003לאו תורפיה דהאי גברא\u0004 \u0005[האם אין עיקרו של איש זה]\u0006 \u0003משום אוקמה בידיה\u0004 \u0005[העמדה בידיו\u0006\u0005]\u0006 \u0003הוא, והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003לא אוקמה\u0004 \u0005[העמיד אותה\u0006 בידיו\u0005],\u0006 ומשום כך חלה עליו נזירות."],["\u0003מזגו לו את הכוס ואמר: \"הריני נזיר ממנו\" —\u0004 \u0003הרי זה נזיר\u0004 נזירות מלאה ואסור בכל דיני נזירות. \u0003מעשה באשה אחת שהיתה שיכורה\u0004 (רוויה מיין), \u0003ומזגו לה את הכוס ואמרה: \"הריני נזירה ממנו\" אמרו חכמים: לא נתכוונה זו\u0004 לנזירות, \u0003אלא לומר \"הרי הוא עלי קרבן\",\u0004 כלומר, אני נודרת איסור מכוס זו בלבד, שאיני רוצה לשתות יותר.","על סגנון המשנה תוהים: וכי זו דרך המשנה להביא \u0003מעשה לסתור\u0004 את דבריה הקודמים?! הלא \u0003אמרת רישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 שמי שמזגו לו את הכוס ואמר \"הריני נזיר ממנו\" — \u0003הרי זה נזיר, והדר תני\u0004 \u0005[וחזר ושנה\u0006\u0005]\u0006 התנא: \u0003מעשה באשה אחת\u0004 שאמרה \"הריני נזירה ממנו\", ואמרו חכמים שנתכוונה לומר שאסרה עליה כוס זו כקרבן. ונדייק: \u0003אלמא בהאי\u0004 \u0005[הרי\u0006 שבכוס זה\u0005]\u0006 בלבד \u0003הוא\u0004 ש\u0003אסור, הא יינא אחרינא\u0004 \u0005[הרי יין אחר\u0006\u0005]\u0006 — \u0003שרי\u0004 \u0005[מותר\u0006\u0005]\u0006 ואין היא נזירה!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה וכך היא שנויה\u0005],\u0006 כלומר, כך צריך להבינה: \u0003מזגו לו את הכוס ואמר \"הריני נזיר ממנו\" —\u0004 \u0003הרי זה נזיר. ואם שיכור הוא\u0004 ומזגו לו כוס \u0003ואמר \"הריני נזיר ממנו\" —\u0004 \u0003אינו נזיר. מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר — משום שנעשה \u0003כמאן דאמר\u0004 \u0005[כמי שאומר\u0006\u0005]\u0006 \u0003\"הרי\u0004 כוס זו \u0003עלי קרבן\" הוא, וכי תימא\u0004 \u0005[ואם תאמר\u0006\u0005]:\u0006 אם זו כוונתו \u0003לימא הכי\u0004 \u0005[שיאמר כך\u0006\u0005]\u0006 במפורש, ומדוע אמר בלשון \"הריני נזיר\"? \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 אם כך אומר, \u0003מייתין\u0004 \u0005[יביאו\u0006\u0005]\u0006 \u0003לי אחרינא\u0004 \u0005[\u0006כוס אחרת\u0005]\u0006 \u0003ומצערן לי\u0004 \u0005[ויצערו אותי\u0006\u0005]\u0006 בשתיה שאיני רוצה בה, לכן מוטב \u0003אימא להו הא מילתא דפסיקא להו\u0004 \u0005[\u0006שאומר להם דבר זה שפסוק, חתוך, להם\u0005]\u0006 ויבינו שאינני רוצה לשתות עוד כלל. וממשיכה המשנה: \u0003ומעשה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003באשה אחת\u0004 שהיתה שיכורה ואמרה כן, שכך פירשו חכמים את דבריה.","האומר \u0003\"הריני נזיר על מנת שאהא שותה יין ומיטמא למתים\",\u0004 כלומר, שקיבל עליו נזירות, אבל עשה תנאי להגביל אותה רק לגידול שיער — \u0003הרי זה נזיר\u0004 גמור, \u0003ואסור בכולן,\u0004 גם בשתיית יין וגם בטומאה למתים.","קיבל נזירות ואמר אחר כך: \u0003\"יודע אני שיש נזירות אבל איני יודע שהנזיר אסור ביין\" —\u0004 \u0003הרי זה אסור\u0004 בכל דיני נזירות, שהנזירות חלה עליו לגמרי, \u0003ור' שמעון מתיר\u0004 שהוא סבור שאין אדם נזיר עד שיקבל על עצמו כל איסורי נזירות. אמר אדם \u0003\"יודע אני שהנזיר אסור ביין, אבל סבור הייתי שחכמים מתירין לי\u0004 לשתות \u0003מפני שאין אני יכול לחיות אלא ביין\",\u0004 \u0003או\u0004 שיתירו לו להיטמא \u0003\"מפני שאני קובר את המתים\" —\u0004 \u0003הרי זה מותר\u0004 בכל הנדר כולו, \u0003ור' שמעון אוסר.\u0004","על מה ששנינו במשנה \"איני יודע שהנזיר אסור ביין\" ר' שמעון מתיר, שואלים: כיון שר' שמעון סבור שאם אדם נודר נדר נזירות שאינו כולל את כל איסורי הנזירות אינו נזיר בכך, \u0003ולפלוג נמי\u0004 \u0005[ושיחלוק גם כן\u0006\u0005]\u0006 \u0003ר' שמעון ברישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 במקרה הראשון במשנה, של האומר \"הריני נזיר על מנת שאהיה שותה יין\"! \u0003אמר ר' יהושע בן לוי:\u0004 אכן, \u0003חלוק היה ר' שמעון אף ברישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 במקרה הראשון. ומה שאמרו במשנה \"ור' שמעון מתיר\" — מתייחס לשני הדינים.","\u0003רבינא אמר: ברישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 \u0003לא פליג\u0004 \u0005[חלק\u0006\u0005]\u0006 \u0003ר' שמעון. מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר \u0003משום דהוה ליה\u0004 \u0005[שהריהו\u0006\u0005]\u0006 כ\u0003מתנה על מה שכתוב בתורה,\u0004 שהוא רוצה להגביל דין מפורש מן התורה, \u0003וכל המתנה על מה שכתוב בתורה —\u0004 \u0003תנאו בטל,\u0004 לפי שאינו יכול לבטל דברי תורה. ושאר דבריו קיימים, ולכן קבלת נזירותו תקפה לכל דיני נזירות. ולעומת טענה זאת — מעירים: \u0003ור' יהושע בן לוי אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך:\u0004 \u0005[האי\u0006 \u0005[זה\u0006\u0005]\u0006 \u0005]\u0006 הלשון שאמר \u0003\"על מנת\"\u0004 — אין משמעו שקיבל עליו את כל דין הנזירות, והוסיף עליו תנאי, אלא \u0003\"כחוץ\" דמי\u0004 \u0005[נחשב\u0006\u0005],\u0006 כאילו אמר מתחילה שהוא מקבל עליו נזירות חוץ מדבר מסויים. ולכן לדעת ר' שמעון לא היתה פה נזירות כלל, שהרי לא קיבל עליו כל איסורי נזירות.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא כשיטתו\u0005]\u0006 של \u0003רבינא: אמר\u0004 אדם \u0003\"הריני נזיר על מנת שאהא שותה יין ומיטמא למתים\" —\u0004 \u0003הרי זה נזיר, ואסור בכולן, מפני שהוא מתנה על מה שכתוב בתורה, וכל המתנה על מה שכתוב בתורה תנאו בטל.\u0004","בקטע האחרון במשנה שנינו שאם אמר: \u0003\"יודע אני שהנזיר אסור ביין\u0004 אבל חשבתי שיתירו לי חכמים לשתות \u0003\"\u0004— חכמים אומרים שהנדר בטל, ור' שמעון אוסר. ומקשים: \u0003והאמרת רישא\u0004 \u0005[והרי אמרת בתחילה\u0006\u0005]\u0006 בדין הקודם במשנה, \"אבל איני יודע שהנזיר אסור ביין\", שהוא דומה לכאורה, כי לדעת תנא קמא \u0003אסור, ור' שמעון מתיר!\u0004 וכיצד הפכו כאן את שיטותיהם? ומשיבים: שנה את הגרסה ו\u0003אימא נמי\u0004 \u0005[אמור גם כן\u0006\u0005]\u0006 כאן: \u0003הרי זה אסור, ור' שמעון מתיר. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]:\u0006 \u0003לעולם לא תיפוך\u0004 \u0005[תהפוך\u0006\u0005]\u0006 את השיטות, ותישאר הגירסה במקומה. אלא יש מקום לחלק בין שני המקרים; \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006"],["\u0003רישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 באומר \"איני יודע שהנזיר אסור ביין\", מדובר \u0003כגון\u0004 ש\u0003נזר\u0004 רק \u0003מחדא\u0004 \u0005[מ\u0006דבר אחד\u0005],\u0006 ומכאן הבדלי השיטות; \u0003לרבנן דאמרי\u0004 \u0005[ל\u0006דעת חכמים שאומרים\u0005]\u0006 ש\u0003אפילו לא נזר אלא מאחת מהן,\u0004 מאיסורי נזיר, מתחייב בנזירות — \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר, ו\u0004לכן הוא \u0003אסור\u0004 בכל. ו\u0003לר' שמעון\u0004 ש\u0003אמר\u0004 שאינו נעשה נזיר \u0003עד שיזיר מכולם\u0004 — הרי זה \u0003מותר.\u0004","ואילו \u0003סיפא\u0004 \u0005[\u0006בסוף\u0005]\u0006 מדובר ש\u0003נדר מכולהו\u0004 \u0005[מכולם\u0006\u0005],\u0006 שקיבל על עצמו נדר נזירות שלם \u0003ואיתשיל מחדא\u0004 \u0005[ו\u0006הוא רוצה להישאל ולהתירו מאחד\u0005]\u0006 מאיסורי הנזירות, שסבר כי חכמים יתירו לו חלק מאיסור נזירותו;","\u0003לרבנן דאמרי\u0004 \u0005[ל\u0006דעת חכמים שאומרים\u0005]\u0006 \u0003אפילו לא נזר אלא מאחת מהן הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר,\u0004 לכן גם \u0003כי מתשיל מחדא מינייהו\u0004 \u0005[כאשר נשאל\u0006 ורוצה שיתירו לו מאחת מהן\u0005] —\u0006 \u0003אישתרי\u0004 \u0005[מותר\u0006\u0005]\u0006 בכל. שכשם שהנזירות חלה בשלימותה על ידי קבלת חלק ממנה, כך היא מותרת בשלימותה על ידי התרת חלק ממנה. ואילו \u0003לר' שמעון\u0004 ש\u0003אמר\u0004 אינו נזיר \u0003עד שיזיר מכולם,\u0004 לכן גם \u0003כי מתשיל נמי מההוא\u0004 \u0005[כאשר נשאל מאותו\u0006 איסור\u0005]\u0006 אינו מותר \u0003עד דמתשיל מכולהו\u0004 \u0005[שיישאל מכולם\u0006\u0005]\u0006 על כל איסורי הנזירות. \u0003משום הכי קתני\u0004 \u0005[כך שנה\u0006\u0005]:\u0006 \u0003ור' שמעון אוסר.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 הסבר אחר: \u0003בנדרי אונסין\u0004 נדרים שנדר אדם מפני אונס \u0003קא מיפלגי\u0004 \u0005[חלוקים\u0006\u0005]\u0006 חכמים ור' שמעון, \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת\u0006\u0005]\u0006 שחלקו בה \u0003שמואל ורב אסי. דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003ארבעה נדרים התירו חכמים\u0004 עקרונית, והם: \u0003נדרי זירוזין,\u0004 שאדם מזרז את חבירו לעשות דבר, ואומר זאת בלשון נדר, כגון המוכר חפץ לחבירו שמדיר עצמו מאותו חפץ אם הלה ישלם לו פחות ממחיר מסויים, אבל באמת אין כוונתו לכך. \u0003נדרי הבאי,\u0004 נדרים שאדם נודר לקיים דבר הבאי, כגון שאמר \"קונם אם לא ראיתי נחש כקורת בית הבד\" וכדומה, שיודע שאינו נכון ובודאי לא התכוון אלא לגוזמה בלבד. \u0003נדרי שגגות,\u0004 שנדר בגלל סיבה מסויימת, וגילה ששגג וטעה בעובדות. \u0003נדרי אונסין,\u0004 שמפני אונס אינו יכול לקיימו.","\u0003ואמר רב יהודה אמר רב אסי: ארבעה נדרים הללו,\u0004 אף על פי שהתירום חכמים, מכל מקום עדיין \u0003צריכין שאלה לחכמים.\u0004 שצריך הנודר לבוא לחכמים ולהישאל על נדרו כדי שיתירו לו במפורש, וכל עוד לא עשה כן — אינם מותרים. סיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי\u0006 הלכה זו של רב אסי לפני\u0005]\u0006 \u0003שמואל, אמר לי:\u0004 ה\u0003תנא קתני\u0004 \u0005[שונה\u0006\u0005]\u0006 \u0003\"התירו חכמים\" ואת אמרת\u0004 \u0005[ואתה אומר\u0006\u0005]\u0006 \u0003צריכין שאלה לחכמים?!\u0004 אלא הכוונה היא שהם מותרים לגמרי.","ובהלכה זו חלוקים גם חכמים ור' שמעון בדין האחרון במשנתנו, שהוא מעין נדרי אונסים, כיון שהוא אנוס לשתות יין או להיטמא למתים; \u0003רבנן סברי\u0004 \u0005[חכמים סבורים\u0006\u0005]\u0006 \u0003כשמואל,\u0004 ולכן אף כאן — מותר הנדר מעצמו גם בלא שנשאל עליו לפני חכם. \u0003ור' שמעון\u0004 סבור \u0003כרב אסי\u0004 שהנדר איננו בטל מאליו, אלא אם ירצה — יבוא ויישאל לחכמים והם יתירו לו את נדרו. וכל עוד לא התירו לו — הריהו נזיר.","האומר \u0003\"הריני נזיר ו\u0004נוסף לזה \u0003עלי לגלח נזיר\",\u0004 כלומר, להביא את הקרבנות שנזיר מביא כשמגלח שערו עליהם, \u0003ושמע\u0004 \u0003חבירו ואמר \"ואני\u0004 נזיר גם כן \u0003ועלי לגלח נזיר\",\u0004 והרי אף זה התחייב בכך בקרבנותיו של נזיר. \u0003אם היו פקחים\u0004 ורוצים לחסוך לעצמם הוצאות — \u0003מגלחין זה את זה,\u0004 כלומר, משלמים זה עבור זה את קרבנות נזירותו, ונמצא שלא הפסיד אחד מהם דבר בנדר הנוסף. \u0003ואם לאו\u0004 \u0005[לא\u0006\u0005],\u0006 שלא חשבו על הענין הזה והביאו כל אחד קרבנותיו לעצמו — \u0003מגלחין נזירים אחרים,\u0004 כלומר, מביאים קרבנות נוספים עבור אחרים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אמר \"הריני נזיר ועלי לגלח נזיר\" ו\u0003שמע חבירו ואמר \"ואני\"\u0004 בלבד, \u0003מהו\u0004 הדין? האם נאמר \u0003\"ואני\" אכוליה דיבורא\u0004 \u0005[על כל הדיבור\u0006\u0005]\u0006 \u0003משמע,\u0004 כלומר, שהוא מקבל על עצמו כל מה שקיבל חבירו, להיות נזיר ולגלח נזיר, \u0003או דלמא אפלגיה דדיבורא\u0004 \u0005[שמא\u0006 רק על חצי הדיבור\u0005]\u0006 \u0003משמע,\u0004 שהשני קיבל על עצמו רק חלק מן הדברים שאמר חבירו. \u0003אם תמצי\u0004 \u0005[תרצה\u0006\u0005]\u0006 \u0003לומר\u0004 כי \u0003אפלגיה דדיבורא\u0004 \u0005[על חצי הדיבור\u0006\u0005]\u0006 \u0003משמע\u0004 ולא על כל הביטוי, האם \u0003ארישא\u0004 \u0005[על תחילת\u0006 דבריו\u0005]\u0006 שאמר \"הריני נזיר\", \u0003או אסיפא\u0004 \u0005[על סוף\u0006 דבריו\u0005]\u0006 שאמר \"ועלי לגלח נזיר\" משמע?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה לדבר ממשנתנו: אמר השני \u0003\"ואני ועלי לגלח נזיר\", אם היו פקחים —\u0004 \u0003מגלחין זה את זה. מדקאמר\u0004 \u0005[ממה ש\u0006הוא אומר\u0005]\u0006 \u0003\"ואני ועלי\" —\u0004 \u0003שמע מינה\u0004 \u0005[למד ממנה\u0006 מכאן\u0005]\u0006 כי \u0003\"ואני\" —\u0004 \u0003אפלגיה דדיבורא\u0004 \u0005[על חצי הדיבור\u0006\u0005]\u0006 נאמר, שאם לא כן לא היה צריך לומר \"ועלי לגלח\", ודי אם אומר \"ואני\". \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 מכאן אמנם אפשר להוכיח כי \u0003אפלגיה דדיבורא\u0004 \u0005[על חצי הדיבור\u0006\u0005]\u0006 \u0003משמע, מיהו\u0004 \u0005[אבל\u0006\u0005]\u0006 יש עוד לברר את השאלה: \u0003ארישא\u0004 \u0005[על\u0006 המחצית של תחילת הדיבור\u0005],\u0006 \u0003או אסיפא\u0004 \u0005[על\u0006 המחצית של סופו\u0005]?\u0006 ומשיבים: לכאורה תלמד \u0003מינה\u0004 \u0005[ממנה\u0006 עצמה\u0005],\u0006 \u0003מדקאמר\u0004 \u0005[ממה ש\u0006הוא אומר\u0005]\u0006 \u0003\"ועלי לגלח\u0004 נזיר \u0003\"\u0004\u0003שמע מינה\u0004 \u0005[למד ממנה\u0006 מכאן\u0005]\u0006 כי \u0003\"ואני\" על תחילת דיבורא\u0004 \u0005[הדיבור\u0006\u0005]\u0006 \u0003משמע\u0004 שמקבל על עצמו להיות נזיר, ולכן הוסיף ואמר שמקבל עליו קרבנות נזיר.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רב יהושע לרבא: ממאי דהכי\u0004 \u0005[ממה,\u0006 מנין שכך\u0005]\u0006 הוא הדבר ש\"ואני\" מתייחס למחצית דיבור? \u0003לעולם אימא\u0004 \u0005[אומר\u0006\u0005]\u0006 \u0003לך\u0004 כי \u0003\"ואני\" —\u0004 \u0003אכוליה דדיבורא\u0004 \u0005[על כל הדיבור\u0006\u0005]\u0006 נאמר, \u0003ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 \u0003משום\u0004 שהוסיף ואמר \u0003\"ועלי\",\u0004 יש לפרש כי \u0003מאי קאמר\u0004 \u0005[מה הוא אומר\u0006\u0005] —\u0006 \u0003ועלי בהא מילתא\u0004 \u0005[בדבר זה\u0006\u0005],\u0006 ולא היה זה אלא פירוש לדבריו, אף שב\"ואני\" לבד היה מתחייב בכל. \u0003דאי\u0004 \u0005[שאם\u0006\u0005]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך\u0006\u0005]\u0006 באופן זה, אם כן \u0003דקתני סיפא\u0004 \u0005[\u0006מה ששנוי בסוף, במשנה הבאה\u0005]\u0006 שאם אמר אדם \u0003\"הרי עלי לגלח חצי נזיר\" ושמע חבירו ואמר \"ואני עלי לגלח חצי נזיר\", התם מי איכא תרתין מילי\u0004 \u0005[שם האם יש שני דברים\u0006\u0005]?\u0006 הרי יש רק התחייבות אחת. \u0003אלא מאי קאמר\u0004 \u0005[מה הוא אומר\u0006\u0005]\u0006 \u0003\"עלי\"\u0004 — \u0003בהא מילתא\u0004 \u0005[בדבר זה\u0006\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 במשנתנו, \u0003כי קאמר\u0004 \u0005[כאשר הוא אומר\u0006\u0005]\u0006 \u0003\"עלי\" —\u0004 \u0003בהא מילתא\u0004 \u0005[בדבר זה\u0006\u0005]\u0006 אמר.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבא: הכי השתא\u0004 \u0005[כך אתה משווה\u0006\u0005]?!\u0006 \u0003אי אמרת בשלמא רישא צריכא סיפא לא צריכא\u0004 \u0005[נניח אם אתה אומר\u0006 שההתחלה נחוצה והסוף איננו נחוץ\u0005],\u0006 שבמשנתנו היה צריך לשם הענין לומר \"ואני... ועלי\", שכל אחד מהם מתייחס לחצי הדיבור של חבירו, ואילו במשנה הבאה אין בדבר צורך, אפשר לומר כי \u0003תני סיפא דלא צריכא\u0004 \u0005[שנה\u0006 את סופה של המשנה שאינו נחוץ\u0005]\u0006 \u0003משום רישא דצריכא\u0004 \u0005[ראשה שנחוץ\u0006\u0005]\u0006 שכך דרך המשנה ששני חלקיה באותו סגנון. \u0003אלא אי אמרת רישא לא צריכא סיפא לא צריכא\u0004 \u0005[אם אומר אתה ש\u0006גם ראשה של המשנה אינו נחוץ וגם סופה אינו נחוץ\u0005]\u0006 ולא היה צריך אף בראשה לפרש \"ועלי\", ובמלה \"ואני\" כבר קיבל עליו את כל דברי חבירו, וכי \u0003תני רישא דלא צריכא ותני סיפא דלא צריכא\u0004 \u0005[שנה ראשה שאינו נחוץ וסופה שאינו נחוץ\u0006\u0005]?\u0006 אלא, ודאי אם במשנה הבאה אין התוספת \"ועלי\" נחוצה, חייבים לומר שהיא נחוצה בחלק הראשון, והדיוק שדייקנו הוא משום כך מקויים.","ולאחר שביררנו את משנתנו לגופה, מביאה הגמרא מה שיש בה לברר בעניינים אחרים. \u0003אמר ר' יצחק בר יוסף אמר ר' יוחנן: האומר לשלוחו\u0004"],["\u0003\"צא וקדש לי אשה\" סתם,\u0004 שלא פירש לו איזו אשה יקדש עבורו — מאותה שעה \u0003אסור\u0004 המשלח \u0003בכל הנשים שבעולם\u0004 עד שידע איזו אשה קידש השליח. כי \u0003חזקה\u0004 ש\u0003שליח עושה שליחותו\u0004 וקידש לו אשה, \u0003וכיון\u0004 ש\u0003לא פריש ליה\u0004 \u0005[פירש לו\u0006\u0005]\u0006 את מי קידש, \u0003הא לא ידע הי ניהו קדיש ליה\u0004 \u0005[הרי אינו יודע איזו\u0006 אשה קידש לו\u0005]\u0006 ואם רוצה הוא לקדש עתה אשה אחרת — יש לחשוש שמא היא קרובתה — בתה או אחותה או אמה — של זו שקידש לו השליח, ואסורה לו.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003ריש לקיש לר' יוחנן:\u0004 שנינו, טמא (זב, זבה, יולדת ומצורע) הבא להיטהר והפריש \u0003קן סתומה,\u0004 שני תורים (\"קן\") או שני בני יונה לקרבן, שאחד מהם צריך להיות עולה ואחד חטאת, וסתם ולא פירש עדיין איזה לעולה ואיזה לחטאת. במקרה \u0003שפרחה גוזל אחד מהן לאויר העולם\u0004 וברח לו, \u0003או שפרחה לבין חטאות המתות,\u0004 שנתערב בין גוזלים אחרים של קרבנות חטאת שנפסלו, שמשום כך צריכים להמיתם, \u0003או שמת אחד מהן\u0004 מן הגוזלים שבקן הסתומה, בכל אחד מן המקרים הללו, מה יעשה — \u0003יקח\u0004 (יקנה) ויביא בעל הקרבן בן \u0003זוג לשני\u0004 שנשאר, ואחר כך יחליט איזה מהם יהיה חטאת ואיזה עולה.","\u0003ואילו\u0004 אם קרה מקרה כזה ב\u0003קן מפורשת,\u0004 שכבר פירש בעל הקרבן איזה מהם עולה ואיזה חטאת, ואחר כך ברח או מת אחד מהם ואינו יודע איזה ברח — \u0003אין לו תקנה\u0004 עוד, שהרי אינו יודע מה עליו להקריב כבן זוג — עולה או חטאת.","ומכל מקום \u0003ואילו שאר קינין בעלמא\u0004 \u0005[סתם\u0006\u0005],\u0006 של שאר האנשים הם \u0003מיתקנן\u0004 \u0005[מתוקנים\u0006\u0005]\u0006 ואין בהם חשש. ואם כדבריך, ר' יוחנן, שצריך לחשוש לכל אשה שמא היא קרובת זו שקידש השליח, \u0003ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 יהיה הדין כך בשאר הקינים? \u0003לימא\u0004 \u0005[נאמר\u0006\u0005]\u0006 גם כן ש\u0003כל חדא וחדא\u0004 \u0005[אחד ואחד\u0006\u0005]\u0006 מן הגוזלות בכל קן בעולם \u0003דלמא האי ניהו\u0004 \u0005[שמא\u0006 זה הוא\u0005]\u0006 הגוזל שהיה כבר מוקדש לשם עולה או לשם חטאת, וברח, וכיצד מתכפר בו אותו אדם!","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 ר' יוחנן לריש לקיש: \u0003קאמינא אנא\u0004 \u0005[אומר אני\u0006\u0005]\u0006 את שיטתי זו וחושש לאיסור, דווקא לגבי \u0003אשה\u0004 \u0003דלא ניידא\u0004 \u0005[שאינה ניידת\u0006\u0005]\u0006 והיא קבועה במקומה, בביתה, וכלל הוא בידינו: שאף על פי שבדרך כלל מניחים אנו שכל דבר המגיע אלינו הריהו מן הרוב, מכל מקום אם הדבר האסור קבוע במקומו, אפילו כאשר הוא מיעוט קטן — דינו כמחצה על מחצה, ואין הולכים אחר הרוב. ומשום כך יש לאסור כל הנשים בעולם. \u0003ואמרת\u0004 \u0005[ואומר\u0006\u0005]\u0006 \u0003לי את\u0004 \u0005[אתה\u0006\u0005]\u0006 בקושייתך זו \u0003איסורא דנייד\u0004 \u0005[איסור שנע\u0006\u0005]\u0006 ממקומו ואינו קבוע? שהרי הגוזל נודד ממקום למקום, ובמקרה כזה הולכים אחר הרוב, ואין חוששים למיעוט.","\u0003וכי תימא\u0004 \u0005[ואם תאמר\u0006\u0005]:\u0006 \u0003הכא נמי נייד\u0004 \u0005[כאן גם כן\u0006 באשה הרי זה איסור נודד\u0005],\u0006 כי \u0003אימור בשוקא אשכח וקדיש\u0004 \u0005[אמור שבשוק מצא\u0006 השליח את האשה וקידש\u0005]\u0006 אותה למשלח, מכל מקום \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 בסופו של דבר \u0003הדרא לניחותא\u0004 \u0005[חוזרת למנוחתה,\u0006 לביתה\u0005]\u0006 ונמצאת שוב במקום קבוע, ולכן יש לדון בה כבאיסור קבוע, ואילו \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003קן, מי הדרא\u0004 \u0005[האם חוזר\u0006\u0005]\u0006 הגוזל לנוח במקום קבוע מסויים? ולכן הולכים בו אחרי הרוב.","\u0003אמר רבא: ומודה ר' יוחנן\u0004 שהמשלח מותר \u0003באשה שאין לה לא בת, ולא בת בת, ולא בת בן, ולא אם, ולא אם אם, ולא אחות,\u0004 שהיו פנויות באותה שעה, שהרי אין לחשוש באשה זו שמא קידש השליח אחת מקרובותיה האוסרות אותה. \u0003ואף על פי שהיתה לה,\u0004 לאותה אשה שהוא רוצה לקדש, \u0003אחות\u0004 (או בת, וכדומה) נשואה בשעה שמינה את השליח \u0003ונתגרשה לאחר מכאן,\u0004 מודה ר' יוחנן \u0003דההיא\u0004 \u0005[שאותה\u0006\u0005]\u0006 אשה שהוא רוצה עכשיו לקדש \u0003שריא\u0004 \u0005[מותרת\u0006\u0005].\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר — \u0003דבההיא שעתא דקאמר ליה, הוה נסיבן לגברי\u0004 \u0005[שבאותה שעה שאמר לו\u0006 לשליח לקדש אשה, \u0005היו נשואות\u0006 קרובותיה \u0005לגברים]\u0006 ואנו אומרים: \u0003כי משוי\u0004 \u0005[כאשר\u0006 אדם עושה\u0005]\u0006 \u0003שליח,\u0004 הרי זה דווקא \u0003במילתא דקיימא קמיה\u0004 \u0005[בדבר העומד לפניו\u0006\u0005],\u0006 כלומר, שדעתו למנותו שליח רק על מה שהוא אפשרי, מצוי, באותה שעה. אבל \u0003במילתא דלא קיימא קמיה\u0004 \u0005[בדבר שאינו עומד לפניו\u0006\u0005] —\u0006 \u0003לא משוי\u0004 \u0005[עושה\u0006\u0005]\u0006 אדם \u0003שליח,\u0004 ולפיכך, הואיל ולא נתמנה לכך, אף אם קידש השליח אחת מקרובותיה של אותה אשה — אין הקידושין חלים, וממילא מותר המשלח באשה זו.","על סברה אחרונה זו מקשים ממשנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006\u0005]:\u0006 האומר \u0003\"הריני נזיר ועלי לגלח נזיר\" ושמע חבירו ואמר \"ואני\u0004 נזיר \u0003ועלי לגלח נזיר\", אם היו פקחין —\u0004 \u0003מגלחין זה את זה, ואם לאו\u0004 \u0005[לא\u0006\u0005] —\u0006 \u0003מגלחין נזירים אחרים.\u0004 ולפי הסברה שאמרנו שאין אדם חושב אלא על מה שמצוי ואפשרי לו באותה שעה יש להקשות: \u0003בשלמא בתראה איכא קדמאה קמיה\u0004 \u0005[נניח\u0006 הנודר האחרון, הרי יש את הראשון לפניו\u0005]\u0006 שנדר בנזיר, ואפשר לומר שהיה בדעתו להתנדב עבורו לשלם את קרבנותיו. \u0003אלא קדמאה מי איכא בתראה קמיה\u0004 \u0005[הראשון, האם האחרון ישנו לפניו\u0006\u0005]?\u0006 שהרי בשעה שנדר הראשון בנזיר לא היה האחרון עוד נזיר, ולפי שיטה זו לא נתכוון להתנדב עבורו, וכיצד יכול הוא להקריב עבורו את קרבנותיו?"],["\u0003אלא\u0004 ודאי יש לפרש כי \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006\u0005],\u0006 זו היתה כוונתו של הראשון: \u0003אי משכחנא דהוי\u0004 \u0005[אם אמצא\u0006 מישהו \u0005שיהיה]\u0006 \u0003נזיר, אגלחיה\u0004 \u0005[אגלח אותו\u0006\u0005].\u0006 ואם כן \u0003הכא נמי הכי קאמר ליה\u0004 \u0005[כאן גם כן\u0006 בקידושין, יש לומר ש\u0005כך אומר לו]\u0006 המשלח: \u0003אי משכחת דמיגרשה, קדיש\u0004 \u0005[\u0006גם אם אתה מוצא אשה שנתגרשה בינתיים, קדש\u0005]\u0006 אותה \u0003לי.\u0004 ואם כן יהיה אסור לו לשאת את אחותה, וקשה לרבא!","ודוחים: \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 יש להבחין בין נזיר שמקבל על עצמו דבר מה לעתיד, לבין שליחות, שבה אנו אומרים: \u0003לא משוי איניש\u0004 \u0005[אין אדם עושה\u0006\u0005]\u0006 \u0003שליח אלא במילתא דמצי עביד השתא\u0004 \u0005[בדבר ש\u0006הוא עצמו יכול לעשות עכשיו\u0005]\u0006 בשעה שהוא ממנה אותו, אבל \u0003במילתא דלא מצי עביד ליה השתא\u0004 \u0005[בדרב שאינו יכול לעשותו עכשיו\u0006\u0005]\u0006 — \u0003לא משוי\u0004 \u0005[אינו עושה\u0006 שליח\u0005]\u0006 ואין זה תלוי בדעתו של המשלח, אלא במהות השליחות, שאינה חלה אלא במה שאפשרי בשעת מינוי השליח. ומשום כך אין קידושי השליח תופסים במי שהיתה נשואה בזמן מינוי השליחות. ולכן, במקרה זה של אחות שהתגרשה, יכול המשלח לשאת את אחותה, וכדברי רבא.","ושואלים: \u0003ו\u0004כי \u0003לא\u0004 יכול למנות שליח באופן זה? \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 שלא כדבריך ממה ששנינו: \u0003האומר לאפוטרופוס שלו\u0004 (ממונה על ביתו): \u0003\"כל נדרים שתדור אשתי מכאן עד שאבוא ממקום פלוני הפר לה\" והפר לה\u0004 האפוטרופוס, \u0003יכול יהו מופרין —\u0004 \u0003תלמוד לומר: \"אישה יקימנו ואישה יפרנו\"\u0004 (במדבר ל, יד), אלו \u0003דברי ר' יאשיה.\u0004 כלומר, כיון שחזר וכפל \"אישה\" למדנו שגזירת הכתוב היא שרק הבעל רשאי להפר נדרי אשתו. \u0003ור' יונתן אומר: מצינו\u0004 (מצאנו) \u0003בכל מקום ששלוחו של אדם כמותו\u0004 ואף האפוטרופוס הריהו שליחו של הבעל ויכול להפר נדרי אשתו.","אם כן, אפילו לדעת ר' יאשיה שאין אפוטרופוס יכול להפר \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום \u0003דאמר רחמנא\u0004 \u0005[שאמרה תורה\u0006\u0005]\u0006 בגזירת הכתוב \u0003\"אישה יקימנו ואישה יפרנו\", הא לאו הכי\u0004 \u0005[הרי לולא כן\u0006\u0005]\u0006 \u0003אפוטרופוס\u0004 היה \u0003מיפר\u0004 גם באופן כזה שהבעל מינה אותו להפר נדרים שתידור אשתו להבא. \u0003ואילו גבי דידיה\u0004 \u0005[אצל\u0006 בעל עצמו\u0005]\u0006 \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 בעל \u0003האומר לאשתו \"כל נדרים שתדורי מכאן ועד שאבא ממקום פלוני יהו קיימין\" —\u0004 \u0003לא אמר כלום.\u0004 ואילו בעל האומר לאשתו \u0003\"\u0004כל נדרים שתדורי מכאן ועד שאבוא ממקום פלוני \u0003הרי הן מופרין\", ר' אליעזר אומר: מופר, וחכמים אומרים: אינו מופר.\u0004","ומבארים: \u0003קא סלקא דעתין\u0004 \u0005[עלה בדעתנו\u0006\u0005]\u0006 לפרש \u0003כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 \u0003אמר ר' יאשיה\u0004 את דבריו שאפוטרופוס אינו מיפר — \u0003אליבא דרבנן\u0004 \u0005[על פי\u0006 דברי חכמים\u0005]\u0006 הוא \u0003דאמרי לא מצי מיפר\u0004 \u0005[שאומרים ש\u0006בעל אינו יכול להפר\u0005]\u0006 נדרים מראש, \u0003ו\u0004אף לשיטתם \u0003אי לאו דאמר רחמנא\u0004 \u0005[אם לא שאמרה תורה\u0006\u0005]\u0006 וגזרה \u0003\"אישה יקימנו ואישה יפרנו\", אפוטרופוס הוה\u0004 \u0005[היה\u0006\u0005]\u0006 \u0003מיפר\u0004 נדרים שכאלה. ואם כן נובע מכאן שאדם יכול להתמנות כשליח אף על דבר שכזה שהמשלח לא יכול לעשותו בזמן שמינה אותו לשליח, וקשה לרבא.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 אמר ר' יאשיה זאת \u0003אליבא\u0004 \u0005[על פי שיטתו\u0006\u0005]\u0006 של \u0003ר' אליעזר,\u0004 ש\u0003אמר מצי מיפר\u0004 \u0005[יכול\u0006 הבעל להפר\u0005]\u0006 מראש ולכן יכול גם למנות שליח באותה שעה! ודוחים: \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 \u0003למה לי,\u0004 כלומר, לו, \u0003לשוויי\u0004 \u0005[לעשות\u0006\u0005]\u0006 \u0003שליח? ליפר\u0004 \u0005[שיפר\u0006\u0005]\u0006 \u0003לה איהו\u0004 \u0005[הוא\u0006 עצמו\u0005]\u0006 מעכשיו! ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003דלמא משתלינא\u0004 \u0005[שמא אשכח\u0006\u0005],\u0006 \u0003או רתחנא\u0004 \u0005[אכעס\u0006\u0005],\u0006 \u0003או מיטרידנא\u0004 \u0005[אהיה טרוד\u0006\u0005]\u0006 ולא אפר בשעה שאצא ממש לדרך, ולכן הוא ממנה שליח לעשות זאת. ואם כן אין להוכיח מכאן דבר.","מי שאמר \u0003\"הרי עלי לגלח חצי נזיר\",\u0004 כלומר, אני מקבל על עצמי חובה לשלם עבור חצי קרבנותיו של נזיר, \u0003ושמע חבירו ואמר \"ואני עלי לגלח חצי נזיר\" —\u0004 \u0003זה מגלח נזיר שלם, וזה מגלח נזיר שלם,\u0004 אלו \u0003דברי ר' מאיר,\u0004 שלדבריו אין נזיר למחצה. \u0003וחכמים אומרים:\u0004 יכולים הם לעשות כנדרם, שיביאו שניהם קרבנותיו של נזיר אחד, \u0003זה מגלח חצי נזיר, וזה מגלח חצי נזיר.\u0004","בהגדרת המחלוקת בין ר' מאיר לחכמים \u0003אמר רבא: הכל מודים, כל היכא\u0004 \u0005[היכן,\u0006 מקום\u0005]\u0006 ש\u0003אמר\u0004 בנדרו \u0003\"חצי קרבנות נזיר עלי\" —\u0004 \u0003חצי קרבן מייתי\u0004 \u0005[מביא\u0006\u0005],\u0006 שהרי נדב רק סכום מסויים. וכמו כן הכל מודים שאם אמר \u0003\"קרבנות חצי נזיר עלי\" —\u0004 \u0003כוליה קרבן בעי איתויי\u0004 \u0005[כל הקרבן צריך להביא\u0006\u0005].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר — \u0003דהא\u0004 \u0005[שהרי\u0006\u0005]\u0006 \u0003לא אשכחן\u0004 \u0005[מצאנו\u0006\u0005]\u0006 \u0003נזירות לפלגא\u0004 \u0005[למחצה\u0006\u0005],\u0006 ומי שאמר \"הריני חצי נזיר\" — הריהו נוהג נזירות שלימה.","\u0003וכי פליגי\u0004 \u0005[וכאשר נחלקו\u0006\u0005],\u0006 דווקא כאשר אמר זאת \u0003בלישנא דמתניתין פליגי\u0004 \u0005[בלשון של משנתנו נחלקו\u0006\u0005];\u0006 \u0003ר' מאיר סבר: כיון\u0004 ש\u0003אמר \"הרי עלי\" —\u0004 \u0003איחייב אכוליה\u0004 \u0005[התחייב על כל\u0006\u0005]\u0006 \u0003קרבן נזירות, וכי קאמר\u0004 \u0005[וכאשר\u0006 הוא אומר\u0005]\u0006 לאחר מכן \u0003חצי נזירות —\u0004 \u0003לאו כל כמיניה\u0004 \u0005[לא הכל בכוחו\u0006\u0005],\u0006 אין ביכולתו לעקור דבר שהתחייב בו. \u0003ורבנן סברי\u0004 \u0005[סבורים\u0006\u0005]:\u0006 \u0003נדר ופתח עמו הוא,\u0004 כלומר, התיר לעצמו את נדר הנזירות במה שאומר שאין כוונתו מתחילה אלא להביא מחצית קרבנות נזירות.","אמר \u0003\"הריני נזיר לכשיהיה לי בן\" ונולד לו בן —\u0004 \u0003הרי זה נזיר.\u0004 ואם \u0003נולד לו בת,\u0004 או \u0003טומטום,\u0004 או \u0003אנדרוגינוס —\u0004 \u0003אינו נזיר,\u0004 שהרי לא נולד לו בן. אבל \u0003אם אמר \"כשיהיה לי ולד\" —\u0004 \u0003אפילו נולד לו בת,\u0004 או \u0003טומטום,\u0004 או \u0003אנדרוגינוס\u0004 — \u0003הרי זה נזיר.\u0004"],["\u0003הפילה אשתו —\u0004 \u0003אינו נזיר,\u0004 שהרי \"ולד\" אמר והתכוון לוולד גמור. \u0003ר' שמעון אומר:\u0004 הואיל ויש ספק בדבר, אם היה אותו הוולד שהפילה בן קיימא מצד עצמו (ומחמת סיבה אחרת הפילתו אמו), או שהיה נפל מצד עצמו, לכן, אין הנודר נפטר בוודאות מחובת נזירותו. ומה יעשה איפוא? — \u0003יאמר\u0004 כך \u0003\"אם היה\u0004 הנפל הזה בעצם \u0003בן קיימא\u0004 מבחינת התפתחותו, אלא תאונה היא שאירעה לו — \u0003הרי אני נזיר חובה\u0004 כפי שנדרתי, \u0003ואם לאו\u0004 \u0005[לא\u0006\u0005] —\u0006 \u0003הרי אני נזיר נדבה\",\u0004 ונוהג בנזירות מכל מקום.","ומחלוקת נוספת במשנתנו: \u0003חזרה\u0004 אשתו \u0003וילדה —\u0004 \u0003הרי זה נזיר,\u0004 שאז חל עליו הנדר לשיטת סתם משנתנו. \u0003ר' שמעון אומר\u0004 לשיטתו: במקרה שכזה יחזור ויקבל עליו נזירות נוספת ו\u0003יאמר \"אם\u0004 היה הוולד \u0003הראשון בן קיימא\u0004 — הנזירות על הוולד \u0003הראשון\u0004 היתה נזירות \u0003חובה, וזו\u0004 שאני נודר כעת היא נזירות \u0003נדבה. ואם לאו\u0004 \u0005[לא\u0006\u0005],\u0006 שלא היה בן קיימא — הנזירות על \u0003הראשון\u0004 היתה נזירות \u0003נדבה, וזו\u0004 נזירות \u0003חובה\".\u0004","על האמור במשנה שאם נדר שיהיה נזיר לכשיוולד לו בן ונולד לו בן — הרי הוא נזיר, שואלים: \u0003האי מאי למימרא\u0004 \u0005[זה מה\u0006 בא לומר\u0005]?\u0006 מובן מאליו שכן הוא! ומשיבים: \u0003משום סיפא\u0004 \u0005[סופה\u0006\u0005]\u0006 של אותה הלכה נאמר הדבר, שאם נולדו לו \u0003בת,\u0004 או \u0003טומטום,\u0004 או \u0003אנדרוגינוס —\u0004 \u0003אינו נזיר.\u0004 ותוהים: גם זה \u0003פשיטא\u0004 \u0005[פשוט\u0006\u0005],\u0006 שהרי \"בן\" אמר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]\u0006 כשאמר \"כשיהיה לי בן\" — לא התכוון לבן ממש, אלא \u0003\"לכשאבנה\" הוא דקאמר\u0004 \u0005[הוא שאמר\u0006\u0005]\u0006 וכוונתו היתה לכל ילד שיוולד לו, ואף אלו בכלל דבריו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 ש\u0003לא\u0004 התכוון אלא לבן.","עוד שנינו במשנה \u0003\"ואם אמר כשיהיה לי ולד\" כו'\u0004 — הרי אף בת, טומטום ואנדרוגינוס בכלל זה. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006\u0005]\u0006 שכן הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]\u0006 דווקא \u0003ולד דמיחשב ביני אינשי בעינן\u0004 \u0005[ולד הנחשב בין האנשים אנו צריכים\u0006\u0005],\u0006 שזאת היתה כוונתו כשנדר, ולכן אלה אינם נחשבים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שלא.","שנינו במשנה: \u0003\"הפילה אשתו\u0004 — \u0003אינו נזיר\",\u0004 אף שכדברי ר' שמעון יש צד ספק בדבר. ומבררים: \u0003מאן קתני לה\u0004 \u0005[\u0006לשיטת מי שנה אותה\u0005]?\u0006 ומשיבים: שיטת \u0003ר' יהודה\u0004 בענין \u0003כרי\u0004 (ערימת תבואה) \u0003הוא.\u0004 שמי שנדר נזירות על מנת שיש בכרי כמות מסויימת של תבואה, ויש ספק אם אכן התקיים תנאו, מבואר שם שר' יהודה סבור שפוסקים להקל.","עוד שנינו במשנה ש\u0003ר' שמעון אומר: יאמר\u0004 הנוזר: \u0003\"אם\u0004 וולד זה \u0003היה בן קיימא —\u0004 \u0003הריני נזיר חובה, ואם לאו\u0004 \u0005[לא\u0006\u0005] —\u0006 \u0003הריני נזיר נדבה\".\u0004 ומביאים: \u0003בעא מיניה\u0004 \u0005[שאל אותו\u0006\u0005]\u0006 \u0003ר' אבא מרב הונא:\u0004 אם אמר \u0003\"הריני נזיר לכשיהיה לי בן\" והפילה אשתו, והפריש קרבן\u0004 לנזירותו ולא הקריבו, \u0003וחזרה\u0004 אשתו \u0003וילדה\u0004 בן, \u0003מהו\u0004 דינו של אותו קרבן שהפריש?","ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי\u0006 שיטת מי\u0005]\u0006 שאלה זו של ר' אבא? \u0003אי אליבא\u0004 \u0005[אם לפי\u0006\u0005]\u0006 שיטתו של \u0003ר' שמעון, מאי תיבעי ליה\u0004 \u0005[מה נסתפק לו\u0006\u0005]?\u0006 \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003אמר ר' שמעון: ספק נזירות להחמיר,\u0004 ואף כאן, מספק שמא הוולד שהפילה היה בר קיימא, צריך להפריש קרבן מיד לאחר שהפילה, ואפילו אם לא ילדה אחרי כן בן שלם. \u0003ואלא\u0004 תאמר שהשאלה היתה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה\u0004 ש\u0003אמר ספק נזירות להקל,\u0004 וזו היא עצם השאלה: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 יהא הדין, האם כבר \u0003קדוש\u0004 הקרבן ואין צריך להקדישו שוב, \u0003או לא קדוש\u0004 ועליו להקדישו עכשיו מחדש?","ושואלים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006\u0005]\u0006 להלכה, שהרי ודאי עתה חלה עליו נזירות וחייב הוא בקרבן! ומשיבים: השאלה היתה \u0003לגיזתו ולעבוד בו,\u0004 שאם הוא כבר קדוש משעה שהקדישו בתחילה — אסור לגזוז את צמרו ולעבוד בו, כבכל בהמת קדשים. ואם עדיין אינו קדוש מותר הדבר. שאלה זו לא נפתרה, ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 במקומה.","ובענין שעוסקת בו משנתנו, בנזירות שאדם מקבל על עצמו לכשיהיה לו בן, \u0003בעא מיניה\u0004 \u0005[שאל אותו\u0006\u0005]\u0006 החכם \u0003בן רחומי מאביי:\u0004 אם אמר אדם \u0003\"הריני נזיר לכשיהא לי בן\" ושמע\u0004 אותו \u0003חבירו ואמר \"ועלי\" מהו\u0004 דינו של השני, מה היתה כוונתו באמירת \"ועלי\"? האם \u0003אדיבורה\u0004 \u0005[על דיבורו\u0006\u0005]\u0006 של הראשון \u0003משמע,\u0004 שכוונתו לקבל על עצמו נזירות, כשיהיה אף לחבירו בן, \u0003או אגופיה\u0004 \u0005[על עצמו\u0006\u0005]\u0006 \u0003משמע,\u0004 שכוונתו לקבל על עצמו נזירות כשיהיה לו עצמו בן?","ומוסיפים עוד על השאלה: גם \u0003אם תמצי\u0004 \u0005[תרצה\u0006\u0005]\u0006 \u0003לומר\u0004 ש\"עלי\" \u0003אגופיה\u0004 \u0005[על עצמו\u0006\u0005]\u0006 \u0003משמע,\u0004 אם \u0003אמר\u0004 אדם \u0003\"הריני נזיר לכשיהא לי בן\" ושמע חבירו ואמר \"ואני\" מהו,\u0004 מה היתה כוונתו של השני באמירה זו? האם אף כאן נפרש ש\u0003אנפשיה קאמר\u0004 \u0005[על עצמו הוא אומר\u0006\u0005]\u0006 וכוונתו לומר: אהיה נזיר כשיהיה לי עצמי בן, \u0003או דילמא הכי קאמר\u0004 \u0005[שמא כך הוא אומר\u0006\u0005]:\u0006 \u0003רחימנא לך כותיך\u0004 \u0005[אוהב אני אותך כמוך\u0006\u0005],\u0006 שגם אני שמח כשיהיה לך בן כמו שאתה תשמח בו, ואף אני אהיה נזיר כשיוולד לך בן. \u0003אם תמצי\u0004 \u0005[תרצה\u0006\u0005]\u0006 \u0003לומר,\u0004 ש\u0003כל\u0004 דבר שהוא אומר לחבירו \u0003באנפיה\u0004 \u0005[בפניו\u0006\u0005]\u0006"],["\u0003כסיפא ליה מילתא\u0004 \u0005[מבייש אותו,\u0006 את הראשון, \u0005הדבר],\u0006 שאין חבירו שותף לשמחתו שלו, וחושב הוא על הולדת בנו שלו, ולכן יש לומר שהשני התכוון באומרו \"ואני\" ללידת בנו של הראשון, יש מקום לשאול: אם \u0003אמר\u0004 אדם \u0003\"הריני נזיר לכשיהא לפלוני בן\" ושמע חבירו ואמר \"ואני\", מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים\u0006\u0005]\u0006 שכיון שנדר השני \u0003שלא בפניו\u0004 של אותו פלוני חבירו המצפה לבן, \u0003אנפשיה קאמר\u0004 \u0005[על עצמו\u0006 הוא אומר\u0005]\u0006 כשאמר \"ואני\" ורצונו לומר כשיוולד לו עצמו בן יהא נזיר, \u0003או דילמא הכי קאמר ליה\u0004 \u0005[שמא כך\u0006 הוא אומר לו השני לראשון\u0005],\u0006 שזו היתה כוונתו כשאמר \"ואני\": \u0003רחימנא ליה כוותיך\u0004 \u0005[אוהב אני אותו\u0006 פלוני כמותך\u0005]\u0006 וכשיהא לאותו פלוני בן אהיה גם אני נזיר. לשאלה זו, כמו לשאלות הקודמות, לא נמצאה תשובה, והרי עדיין \u0003תיבעי\u0004 \u0005[תישאל\u0006\u0005]\u0006 השאלה.","אמר אדם \u0003\"הריני\u0004 מקבל עלי עתה להיות \u0003נזיר, ו\u0004גם אני מקבל על עצמי להיות \u0003נזיר כשיהיה לי בן\", התחיל מונה את שלו,\u0004 כלומר, את נדר הנזירות שנדר תחילה, \u0003ואחר כך\u0004 בתוך זמן נזירותו \u0003נולד לו בן —\u0004 \u0003משלים את\u0004 נדר הנזירות \u0003שלו ואחר כך מונה\u0004 מתחילתו \u0003את\u0004 נדר הנזירות שקיבל ב\u0003של בנו.\u0004 אבל אם אמר \u0003\"הריני נזיר כשיהיה לי בן, ו\u0004גם הריני \u0003נזיר\",\u0004 אם \u0003התחיל מונה את שלו ואחר כך\u0004 בתוך זמן נזירותו זו \u0003נולד לו בן —\u0004 \u0003מניח את\u0004 הנזירות \u0003שלו ומונה את של בנו\u0004 שהרי הנדר על בנו קדם, \u0003ואחר כך משלים את\u0004 הנזירות \u0003שלו.\u0004","בעקבות האמור במשנה \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רבא: אמר \"הריני נזיר\u0004 נזירות רגילה של שלושים יום \u0003לאחר עשרים יום, ו\u0004כן הריני נזיר \u0003מעכשיו מאה יום\", מהו\u0004 הדין? מן הצד האחד, \u0003כיון דהלין\u0004 \u0005[שאלה\u0006\u0005]\u0006 \u0003מאה\u0004 הימים של הנזירות \"מעכשיו\" \u0003ב\u0004תוך \u0003עשרין\u0004 הימים הראשונים \u0003לא שלמין\u0004 \u0005[מושלמים\u0006\u0005] —\u0006 \u0003לא חיילין\u0004 \u0005[חלים\u0006\u0005]\u0006 עליו כלל ימי הנזירות עד לאחר עשרים יום, \u0003או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 אף אם הוא מפסיק בנזירות אחרת, \u0003כיון דאית ליה\u0004 \u0005[שיש לו\u0006\u0005]\u0006 שלושים יום של \u0003גידול שער לבסוף,\u0004 שהרי נותרו לו עוד שמונים ימים לנזירות זו לאחר שימנה את הנזירות השניה, נאמר ש\u0003חיילין\u0004 \u0005[חלים\u0006\u0005]\u0006 עליו מעכשיו ימי הנזירות הארוכה, וימנה עשרים יום, ואחר כך ימנה את הנזירות השניה שהיא בת שלושים יום, ואחר כך יגלח, וישלים עוד שמונים יום לנזירות הארוכה.","ושואלים: \u0003ותיבעי ליה\u0004 \u0005[ושתישאל לו\u0006 לרבא\u0005]\u0006 השאלה ב\u0003נזירות מועטת,\u0004 לאו דווקא במאה ימים אלא בנזירות סתם, באופן שלא ייוותרו לו שלושים יום מן הנזירות הראשונה לאחר שישלים את השניה! ומשיבים: \u0003חדא מגו חדא קא מיבעיא ליה\u0004 \u0005[אחת מתוך אחת נשאלה לו\u0006\u0005],\u0006 כלומר, שאלתו זו של רבא נשאלה מתוך שאלה אחרת, ואף ממנה משתלשלת שאלה אחרת, והמבנה השלם של שאלה זו צריך להיות כך:"]]};
